    Add("{unit} has retrieved the Book of Medivh from its pedestal, and now prepares to harness its untold power.", "{unit}已从基座上取走麦迪文之书，正准备驾驭其难以估量的力量。");
    Add("{unit} has retrieved the Book of Medivh from its pedestal. With its power, we can summon the full might of the Burning Legion from the depths of the Twisting Nether.", "{unit}已从基座上取走麦迪文之书。借助它的力量，我们可以从扭曲虚空的深处召唤燃烧军团的大军。");
