    Add("'{locale}' is not a locale Warcraft III loads. Known names:", "「{locale}」不是《魔兽争霸3》会加载的语言。已知名称：");
    Add("4 free {warden}s appear at the Broken Isles, and you learn to train {warden}s from the {vault} and from {bastion}s", "破碎群岛出现 4 名免费的{warden}，你还能学会从{vault}和{bastion}训练{warden}");
    Add("A Vial of the Sunwell appears on the ground, and the Sunwell permanently loses 500 maximum mana", "一瓶太阳之井井水出现在地面上，太阳之井永久失去 500 点最大魔法值");
    Add("A global conflict for control of Azeroth is brewing. The great powers set their sights on distant shores as allies, new and old alike, seek to bolster their own.", "一场争夺艾泽拉斯控制权的全球冲突正在酝酿。各大势力已将目光投向遥远的彼岸，而新老盟友也都在设法壮大自身。");
    Add("A great portal to the depths of the Twisting Nether has been opened by {hero}. The Burning Legion steps forth, heralding the beginning of the end.", "{hero}已开启一道通往扭曲虚空深处的大型传送门。燃烧军团踏步而出，昭示着末日的开端。");
    Add("A mighty tentacle from the depths.", "来自深渊的强大触须。");
    Add("A millenia ago, the Night Elves soundly defeated my Qiraji and drove them scurrying back into Ahn'qiraj. If I am to succeed in my domination of Azeroth, the second War of the Shifting Sands must begin with their demise.", "千年之前，暗夜精灵彻底击败了我的其拉虫人，将他们赶回了安其拉。我若想成功征服艾泽拉斯，第二次流沙之战就必须以他们的覆灭拉开序幕。");
    Add("A new base at Borean Tundra in Northrend", "在诺森德的北风苔原获得一座新基地");
    Add("A new base near Dragonblight in Northrend, and Arthas revives there", "在诺森德龙骨荒野附近获得一座新基地，阿尔萨斯将在那里复活");
    Add("A new generation of Mages are in dire need of council. The exiled Aegwynn, used to be a Guardian of Tirisfal. Grabbing her attention will require powerful wizards.", "新一代的法师亟需指引。被流放的艾格文曾是提瑞斯法的守护者。要引起她的注意，需要强大的巫师。");
    Add("A small murloc skirmish is attacking Southshore, push them back", "一小股鱼人正在袭击南海镇，把他们打退");
    Add("A small troll skirmish is attacking Dun Morogh. Push them back!", "一小股巨魔正在袭扰丹莫罗。把他们赶回去！");
    Add("A vile group of Murloc is terrorizing Thelsamar. Destroy them!", "一群邪恶的鱼人正在恐吓塞尔萨玛。消灭他们！");
    Add("A {unit} under the control of {faction} has encroached on the shores of Northrend. Soon they will feel the biting chill of death.", "由{faction}控制的{unit}已侵入诺森德的海岸。很快他们就会感受到死亡的刺骨寒意。");
    Add("A09X", "霜冻吐息");
    Add("A0AK", "法力回复");
