    Add("ACss", "自毁");
    Add("Aall", "共享商店");
    Add("Acquire {item}", "获取 {item}");
    Add("Adora Nightshade", "阿多拉·夜影");
    Add("Advanced", "进阶");
    Add("Adventurers from Azeroth are threatening me, your god. Annihilate them.", "来自艾泽拉斯的冒险者正在威胁我，你们的神。将他们彻底消灭。");
    Add("Aegwynn will also be trainable at the altar.", "艾格文也可在祭坛中训练。");
    Add("Aeloras Lightwarden", "艾洛拉斯·圣光守卫");
    Add("Aerial warriors of the Silithid.", "异种蝎的空中战士。");
    Add("Aerie Peak", "鹰巢山");
    Add("Afrb", "霜冻吐息");
    Add("After months of digging, excavating, and tomb raiding,", "历经数月的挖掘、开凿与盗墓，");
    Add("After the disastrous voyage through the Twisting Nether, the Exodar crash-landed on Azuremyst Isle. We need to secure the surrounding islands for resources.", "在穿越扭曲虚空的灾难性航行之后，埃索达坠毁在秘蓝岛上。我们需要控制周边的岛屿以获取资源。");
    Add("Against all odds, the Scarlet Crusade has reclaimed and rebuilt the lands of Lordaeron, filling its cities and fields with the beginnings of a new generation. Having proven itself capable of far more than simple vengeance, the Crusade receives the Light's ultimate blessing.", "尽管困难重重，血色十字军仍夺回并重建了洛丹伦的土地，让新的世代开始在它的城市与田野间萌生。既然已证明自己所能远不止简单的复仇，十字军便得到了圣光的至高赐福。");
    Add("Agamand the True", "忠诚的阿伽曼德");
    Add("Aggronor the Mighty", "强大的阿格拉诺");
    Add("Agility", "敏捷");
