    Add("All players get bonus income for the first 10 turns. Use it to train a strong army, complete your starting quests, and secure Control Points.", "所有玩家在前 10 个回合都会获得额外收入。用它来训练一支强大的军队、完成开局任务并夺取控制点。");
    Add("All text settings set to", "所有文本设置已设定为");
    Add("All units deal {damage}% extra damage and regain {mana}% of the mana cost of abilities. Only active while your team controls the Sunwell, the Well of Eternity, Black Temple, or Nordrassil.", "所有单位造成额外{damage}%伤害，并返还技能法力消耗的{mana}%。仅当你的队伍控制太阳之井、永恒之井、黑暗神殿或诺达希尔时生效。");
    Add("All-Seeing", "全视");
    Add("Alleria Windrunner", "奥蕾莉亚·风行者");
    Add("Allows Orcish units to increase their attack rate and movement speed temporarily. Blood Brothers is now available to Grunts", "使兽人单位能够暂时提高攻击速度和移动速度。兽人步兵现在可以施展歃血兄弟。");
    Add("Allows {guildRanger}s to be trained from {bastion}s", "允许从{bastion}训练{guildRanger}");
    Add("Altar", "祭坛");
    Add("Altar of Elements", "元素祭坛");
    Add("Altar of Prowess", "勇武祭坛");
    Add("Alterac", "奥特兰克");
    Add("Although Stromgarde's strength has dwindled since the days of the Arathorian Empire, it remains a significant bastion of humanity. They could be convinced to mobilize their forces for Stormwind.", "尽管自阿拉索帝国时代以来，斯托姆加德的国力已然衰落，它仍是人类重要的堡垒。或许可以说服他们为暴风城出兵。");
    Add("Amora Eagleye", "阿莫拉·鹰眼");
    Add("An ancient blade from the time of the Black Empire itself. The Dagger has a mind of its own and tries to corrupt whoever wields it. It has been lost to time.", "一柄来自黑暗帝国时代的古老利刃。这把匕首自有其意志，会试图腐化每一个持有它的人。它早已湮没于时光之中。");
    Add("Anara Chillwind", "安娜拉·冰风");
