    Add("Archimonde gains {stat} Strength, Agility, and Intelligence, and the Druids are defeated", "阿克蒙德获得{stat}点力量、敏捷与智力，德鲁伊们则被击败");
    Add("Archimonde the Defiler has been banished from Azeroth, marking the end of his second failed invasion.", "污染者阿克蒙德已被逐出艾泽拉斯，他第二次入侵的失败就此画上句号。");
    Add("Archimonde... After ten thousand years, how is it possible?", "阿克蒙德……已经过去一万年了，这怎么可能？");
    Add("Archmage Antonidas has been cut down, his vast knowledge forever lost with his death. The mages of Dalaran have lost their brightest mind.", "大法师安东尼达斯已被斩杀，他浩瀚的学识随其死亡永远失传。达拉然的法师们失去了他们最聪慧的头脑。");
    Add("Ardalis Starshield", "阿达利斯·星辰之盾");
    Add("Are you still upset that I stole Jaina from you, Kael?", "你还在为我抢走吉安娜的事耿耿于怀吗，凯尔？");
    Add("Ariel Darkmoon", "艾蕊尔·暗月");
    Add("Arius the Seeker", "求知者阿瑞乌斯");
    Add("Armor inhabited by an elemental.", "由元素寄居的铠甲。");
    Add("Arthas Menethil is the sole heir to the Lordaeron crown. His father, ever obstinate in his old age, denies the existential threat of the Scourge and forbids Arthas from bringing the fight to Northrend. The crown prince will simply have to take matters into his own hands.", "阿尔萨斯·米奈希尔是洛丹伦王位唯一的继承人。他的父亲年迈固执，拒不承认天灾的存亡威胁，并禁止阿尔萨斯将战火引向诺森德。这位王储只能亲自出手了。");
    Add("Arthas abandons Lordaeron to join the Scourge; learn to train {hero} from the {altar}", "阿尔萨斯背弃洛丹伦，加入天灾军团；学会从{altar}中训练{hero}");
    Add("Arthas becomes the King of Lordaeron, gains the {crown}, and he can no longer permanently die. Learn to build {tower}s. Your {knight}s become {gallantKnight}s and your {huntsman}s become {arbalest}s", "阿尔萨斯成为洛丹伦国王，获得{crown}，且不再会永久死亡。学会建造{tower}。你的{knight}将变为{gallantKnight}，你的{huntsman}将变为{arbalest}");
    Add("Arthas becomes the Lich King, the Frozen Throne loses its abilities, and you regain the Domination power if you don't have it", "阿尔萨斯成为巫妖王，冰封王座失去其技能，若你尚未拥有统御之力则重新获得它");
    Add("Arthas has ascended the Frozen Throne itself and shattered Ner'zhul's frozen prison. Ner'zhul and Arthas are now joined, body and soul, into one being: the god-like Lich King.", "阿尔萨斯登上了冰封王座，击碎了耐奥祖的冰封牢笼。耐奥祖与阿尔萨斯如今身心合一，化为一体：神一般的巫妖王。");
    Add("Artifacts are unique items that can grant major advantages. You can find out where Artifacts are using the Artifact Book.", "神器是能带来巨大优势的独特物品。你可以用神器图鉴查看神器的位置。");
    Add("Artifacts are unique items that can grant major advantages. You can find out where Artifacts are using the Artifact Menu at the top-left of your screen.", "神器是独特的物品，能带来巨大的优势。你可以通过屏幕左上方的神器菜单查看神器的位置。");
    Add("As foretold by the Lich King, Kel'thuzad has been slain. Unseen to his assailants, his spirit is carried away by the howling winds of Northrend and reconstituted at the base of Icecrown Citadel.", "正如巫妖王所预言，克尔苏加德已被杀死。在他的袭击者未曾察觉之时，他的灵魂被诺森德呼啸的寒风卷走，并在冰冠堡垒的基座处重铸成形。");
    Add("Ashbringer", "灰烬使者");
    Add("Ashenvale has awakened!", "灰谷已经苏醒！");
    Add("Asp1", "法球");
    Add("Aspa", "蜘蛛攻击");
    Add("Asph", "法球");
