    Add("At last! The Tomb of Sargeras is found!", "终于！眼前就是萨格拉斯之墓了！");
    Add("At last, the way to the World Tree is clear! Witness the end, you mortals! The final hour has come.", "终于！世界之树就在眼前！见证末日吧，凡人们！最终的时刻到来了！");
    Add("At the end of the Second War, Khadgar remained in Draenor to seal the Dark Portal, effectively ending the conflict. He has been stranded deep in Outland ever since.", "第二次大战结束时，卡德加留在德拉诺封印黑暗之门，从而终结了那场冲突。此后他便一直困守外域深处。");
