    Add("Basic", "基础");
    Add("Basic tower. Has no attack.", "基础塔楼。没有攻击力。");
    Add("Basic worker unit. Can harvest gold, build structures, and Repair.", "基础工人单位。可以采集黄金、建造建筑并进行修理。");
    Add("Battered but unbroken, the Tauren tribes complete their long march and raise Thunder Bluff on the plains of Mulgore.", "虽历经磨难却未曾屈服，牛头人部族完成了漫长的迁徙，在莫高雷的平原上建起了雷霆崖。");
    Add("Be wary. The elves likely wait in ambush.", "当心。精灵可能就埋伏在前面。");
    Add("Beazel Bludstone", "比泽尔·石兄");
    Add("Before he became the Lich King, Ner'zhul was the chieftain and elder shaman of the Shadowmoon Clan. Perhaps something of his former self still survives within the Frozen Throne.", "在成为巫妖王之前，耐奥祖是影月氏族的酋长与长老萨满。也许在冰封王座之中，他昔日的自我仍有残存。");
    Add("Before retreating to Outland, Illidan was visited by the demon lord Kil'jaeden, who demanded that he destroy the Legion's foes. The Deceiver has now come to claim his due, and this time he will not be denied.", "在退回外域之前，恶魔领主基尔加丹曾造访伊利丹，命他消灭军团的敌人。如今欺诈者前来索取属于他的一切，而这一次，他不会接受拒绝。");
    Add("Before the First War, all of humanity was united under the banner of the Arathorian Empire. Reclaim its greatness by uniting mankind once again.", "第一次大战之前，全人类曾在阿拉索帝国的旗帜下团结一心。再次统一人类，重现它的辉煌。");
    Add("Before the Plague wiped out Stratholme, Saiden had established himself there as Lord Commander of the Silver Hand. This once-glorious city must be reclaimed.", "在瘟疫毁灭斯坦索姆之前，赛丹已在那里确立了自己作为白银之手总指挥官的地位。这座昔日辉煌的城市必须被夺回。");
    Add("Before this time of mortals, The Old Gods ruled this world, our empires stretching to every corner. I will bury their cities, and return Azeroth to primordial chaos.", "在凡人时代到来之前，上古之神统治着这个世界，我们的帝国疆域曾延伸至每一个角落。我将埋葬他们的城市，让艾泽拉斯重归太初的混沌。");
    Add("Before this time of mortals, the Old Gods ruled this world, our empires stretching to every corner. I will bury their cities, and return Azeroth to primordial chaos.", "在凡人时代到来之前，上古之神统治着这个世界，我们的帝国疆域曾延伸至每一个角落。我将埋葬他们的城市，让艾泽拉斯重归太初的混沌。");
    Add("Benchmark a spell. Use -bench help for usage.", "对某个法术进行性能测试。用法请见 -bench help。");
    Add("Beneath Eldarath and the coast of Azshara lies a convergence of ancient ley lines, once mapped and manipulated by the Highborne. Lady Vashj believes the remnants of their arcane workings can still be studied to uncover knowledge thought to be long-lost.", "在埃达拉斯与艾萨拉海岸之下，古老的魔网交汇成脉。上层精灵曾勘测并操弄这些魔网。瓦丝琪女士相信，他们奥术造物的残迹仍可供研究，从而揭示早已失传的知识。");
    Add("Benedict Ironfaith", "本尼迪克特·铁信");
    Add("Beyond our local conflicts lies a larger war for the fate of Azeroth itself. It will reach us eventually, whether we wish it or not.", "在我们局部的纷争之外，还有一场关乎艾泽拉斯自身命运的更大战争。无论我们是否愿意，它终将降临到我们头上。");
    Add("Black Empire of N'zoth", "恩佐斯的黑暗帝国");
    Add("Blackrock Spire has been razed.", "黑石塔已被夷为平地。");
