    Add("Buzan the Fearless", "无畏者布赞");
    Add("By examining the ley line nexus and the remnants of Highborne arcane structures, the Illidari recover forgotten principles of the arcane, expanding their understanding of Azeroth’s ancient magic.", "通过勘察魔网节点与上层精灵奥术建筑的残迹，伊利达雷重拾了被遗忘的奥术原理，加深了他们对艾泽拉斯远古魔法的理解。");
    Add("C'Thun", "克苏恩");
    Add("C'thun and his Qiraji followers", "克苏恩及其其拉虫人追随者");
    Add("C'thun gain", "克苏恩获得");
