    Add("C'thun is currently watched by a Titan Construct. We must rid the temple of hostiles and destroy the Titan to free our god.", "克苏恩目前正被一个泰坦造物看守。我们必须清除神殿中的敌人，并摧毁这个泰坦，才能解救我们的神。");
    Add("C'thun learn to cast {ability}", "克苏恩学会施放{ability}");
    Add("C'thun, the great distorter of flesh, needs to amass samples from many beings to create", "克苏恩，伟大的血肉扭曲者，需要从诸多生灵身上采集样本，方能创造出");
    Add("CAPITAL DAMAGED", "都城受损");
    Add("CAPITAL DESTROYED", "都城已被摧毁");
    Add("Cairne is welcomed in Highmountain like a lost-long friend. Eager to explore the world and fight alongside their long-lost brethren, the Highmountain send their best hunters to support the Horde, and offer their home as a traveler's respite.", "凯恩在至高岭受到了久别重逢般的欢迎。至高岭牛头人渴望探索这个世界，与他们失散已久的同胞并肩作战，于是派出了最优秀的猎手支援部落，并献出他们的家园作为旅人的休憩之所。");
    Add("Cairne's spirit has passed on from this world. The Tauren have already begun to revere their fallen ancestor.", "凯恩的灵魂已离开这个世界。牛头人已经开始崇敬他们陨落的先祖。");
    Add("Caledor Sunfury", "卡莱多尔·日怒");
    Add("Calyndra Dawnbringer", "卡琳德拉·黎明使者");
    Add("Calythar Nighttrident", "卡利萨尔·暗夜之戟");
    Add("Can now train Garrosh from the {altar} and research the Warsong expedition from the {shipyard}", "现在可以从{altar}中训练加尔鲁什，并在{shipyard}研究战歌远征");
    Add("Can the formalities, Uther. I'm not king yet. It's good to see you.", "不必拘礼，乌瑟尔。我还不是国王。很高兴见到你。");
    Add("Can your blood atone for genocide, orc? Your Horde killed countless innocents with its rampage across Stormwind and Lordaeron. Do you really think you can just sweep all that away and cast aside your guilt so easily? No, your kind will never change, and I will never stop fighting you.", "你们的血还得清屠城的债吗 ，兽人？你的部落在暴风城和洛丹伦肆虐时，杀害的无辜百姓不计其数。你真以为你们的血债能一笔勾销，犯下的罪行能一了百了？不，你们死性难改，我要跟你们血战到底。");
    Add("Captain, are all my forces accounted for?", "队长，我的部队都到齐了吗？");
    Add("Cast {spell}", "施放 {spell}");
    Add("Caster Production", "施法单位生产");
