    Add("Come forth, Lord Archimonde! Enter this world, and let us bask in your power!", "降临吧，阿克蒙德大人！让我们沐浴在您力量的荣光之中！");
    Add("Come no further, weakling!  Lord Tichondrius commanded us to kill anyone attempting to enter this place, and we shall.", "到此为止了，弱者！提克迪奥斯大人有令，胆敢进入此地者格杀勿论，我们绝不手软！");
