    Add("Crown Prince Arthas, and what remains of his forces, have landed on the shores of Northrend and established a base camp.", "王储阿尔萨斯及其残存的部队已在诺森德海岸登陆，并建立了营地。");
    Add("Crown of Lordaeron", "洛丹伦王冠");
