    Add("Daelin Proudmoore gains 4000 experience", "戴林·普罗德摩尔获得 4000 点经验值");
    Add("Daelin Proudmoore led his people against the savage Orcs during the Second War. Now his old enemies ride forth once more, and he won't be satisfied until he brings the battle to their doorstep.", "第二次大战期间，戴林·普罗德摩尔曾率领他的人民抵御野蛮的兽人。如今他的宿敌再度挥师而来，若不将战火烧到他们的家门口，他绝不会善罢甘休。");
    Add("Daelin stands before the Hellfire Citadel, towering over the landscape like a twisted monument to the Orc's brutality. He vows that, this time, he won't merely drive the Orcs back - he'll lead his men to conquer these brutal lands and slaughter them all.", "戴林伫立在地狱火堡垒之前，那堡垒如一座扭曲的兽人暴行纪念碑般高耸于大地之上。他立誓这一次不仅要击退兽人——他还要率领部下征服这片残暴的土地，将他们赶尽杀绝。");
    Add("Dagda", "达戈达");
    Add("Dagren the Orcslayer", "兽人克星达格伦");
    Add("Dalaran has empowered Jaina to be the new Guardian of Tirisfal, endowing her with a portion of the Council of Tirisfal's power.", "达拉然已赋予吉安娜力量，让她成为新的提瑞斯法的守护者，并将提瑞斯法议会的一部分力量授予了她。");
    Add("Dalaran has fallen. Those who managed to survive its destruction travel west, to the distant lands of Kalimdor. They hope that this new world will treat them more kindly than the one they left behind.", "达拉然已经陷落。那些在毁灭中幸存下来的人向西远行，前往遥远的卡利姆多。他们希望这片新天地能比他们抛下的一切待他们更温柔些。");
    Add("Dalaran's Earth Golems have been infused with living crystal.", "达拉然的土元素已被注入活体水晶。");
    Add("Danath Trollbane", "达纳斯·托尔贝恩");
    Add("Darius Crowley has been imprisoned since the Northgate rebellion. If Gilneas were to fall into grave peril, an early release might be necessary.", "达利乌斯·克罗雷自北门叛乱以来一直被囚禁。倘若吉尔尼斯陷入重大危难，或许有必要提前释放他。");
