    Add("Enemy {descriptor} unit has entered {rect}", "敌方{descriptor}单位已进入{rect}");
    Add("Eons ago, the council that led the Eredar was the Triumvirate. If Velen could reconquer Argus, he could reform the Crown of the Triumvirate", "万古之前，领导艾瑞达的议会便是执政团。倘若维伦能重夺阿古斯，他就能重铸执政团之冠");
    Add("Eryndor Tidewarden", "埃林多尔·潮汐守卫");
    Add("Essence of Murmur", "摩摩尔的精华");
    Add("Etyr", "泰兰德·语风");
    Add("Ever since the War of the Ancients ten thousand years ago, Malfurion Stormrage and his druids have slumbered within the Barrow Den. Now, their help is required once again.", "自万年前的上古之战以来，玛法里奥·怒风与他的德鲁伊们一直在兽穴中沉睡。如今，人们再度需要他们的援助。");
    Add("Every faction can build an item shop that contains useful purchasable items.", "每个阵营都可以建造一座物品商店，其中出售实用的物品。");
    Add("Every player shares vision with their extended allies", "每位玩家与其延伸盟友共享视野");
