    Add("Gain 250 gold and a base in Area 52", "获得 250 黄金和一处位于 52 区的基地");
    Add("Gain 500 gold.", "获得 500 黄金");
    Add("Gain Control all buildings in Shimmering Flats", "夺取闪光平原所有建筑的控制权");
    Add("Gain Control of all buildings and units in the Twilight landing area, learn to train X'korr the Compelling from the {altar} and the ability to train 1 {forgottenOne} from the {mutationCircle}", "获得暮光登陆场区域所有建筑与单位的控制权，学会从{altar}中训练夺心者克索尔，并获得从{mutationCircle}训练 1 个{forgottenOne}的能力");
    Add("Gain Control of all buildings in the Throne of the Four Winds", "夺取四风王座所有建筑的控制权");
    Add("Gain Control of all buildings in the Vortex Pinnacle, learn to train Al-Akir from the {altar}", "获得旋云之巅所有建筑的控制权，学会从{altar}中训练奥拉基尔");
    Add("Gain Nordrassil, the Darnassus base, the Moonglade base, the hero Malfurion, and the artifact G'hanir", "获得诺达希尔、达纳苏斯基地、月光林地基地、英雄玛法里奥以及神器加尼尔");
    Add("Gain a new capital at Grizzly Hills that can research a powerful upgrade for your {unit}, and learn to train the hero Ursoc from the {altar}. If you're allied to the Scourge, {hero}'s starting experience is halved", "在灰熊丘陵获得一座新的都城，可为你{unit}研究一项强大的升级，并可学会从{altar}中训练英雄乌索克。若你与天灾军团结盟，{hero}的初始经验值减半");
    Add("Gain an Outpost in Darkshore and Maraad is now trainable at the altar.", "在黑海岸获得一座前哨，且玛拉德现在可在祭坛中训练。");
    Add("Gain control of Echo Isles, {removeUnit}s are upgraded to {addUnit}s and learn to train {shadowpriest}s. Alternatively, earn {gold} gold and up to {experience} experience points, shared among all your heroes—the fewer heroes you control, the less experience each receives. Additionally, enhance both {blademaster}s' and {korkronElite}s' maximum mana by 250 and mana regeneration by 50%.", "获得回音群岛的控制权，{removeUnit}将升级为{addUnit}，并可训练{shadowpriest}。或者，获得{gold}黄金以及至多{experience}点经验值，由你麾下所有英雄共享——你控制的英雄越少，每位英雄获得的经验就越少。此外，使{blademaster}和{korkronElite}的魔法值上限提高 250 点，魔法恢复速度提高 50%。");
    Add("Gain control of Gilneas", "获得吉尔尼斯的控制权");
    Add("Gain control of Grom Hellscream; Gargok is permanently removed.", "获得格罗姆·地狱咆哮的控制权；加戈克被永久移除。");
    Add("Gain control of High Bank, earn 225 gold, and {hero} gains 2000 experience", "获得滩头堡的控制权，赢得 225 黄金，且{hero}获得 2000 点经验值");
    Add("Gain control of Naga units and buildings in the Cape of Stranglethorn", "荆棘谷海角纳迦单位与建筑的控制权");
    Add("Gain control of Quel'danil Lodge and its rangers", "获得奎尔丹尼小屋及其游侠的控制权");
    Add("Gain control of Stonemaul, {removeUnit}s' are upgraded to {addUnit}s' and unlock the ability to train {ogreMagi}s. Alternatively, earn {gold} gold and up to {experience} experience points, shared among all your heroes—the fewer heroes you control, the less experience each receives. Additionally, enhance both {blademaster}s' and {korkronElite}s' attack damage by 10, movement speed by 20 and hit points by 250.", "获得石槌的控制权，{removeUnit}将升级为{addUnit}，并解锁训练{ogreMagi}的能力。或者，获得{gold}黄金以及至多{experience}点经验值，由你麾下所有英雄共享——你控制的英雄越少，每位英雄获得的经验就越少。此外，使{blademaster}和{korkronElite}的攻击力提高 10 点，移动速度提高 20，生命值提高 250 点。");
    Add("Gain control of Tempest Keep, and learn to build {ancientPool}s and {artificerCourt}s", "获得风暴要塞的控制权，并学会建造{ancientPool}和{artificerCourt}");
    Add("Gain control of a base in Icecrown", "在冰冠冰川取得一处基地的控制权");
    Add("Gain control of a small base in Alterac, learn to generate a portal to Alterac using the Argus Teleporter, and gain a {dreadShrine} in each of the following Scourge bases: Deathknell, Stratholme Coast, and Scholomance. Mal'ganis improves his Vampiric Siphon ability.", "获得奥特兰克一座小型基地的控制权，学会使用阿古斯传送器生成通往奥特兰克的传送门，并在以下每座天灾基地各获得一个{dreadShrine}：丧钟镇、斯坦索姆海岸与通灵学院。玛尔加尼斯强化他的吸血虹吸技能。");
    Add("Gain control of all buildings in Desolace", "获得凄凉之地所有建筑的控制权");
    Add("Gain control of all buildings in Drak'tharon Keep and learn to train {hero} from the {altar}", "获得达克萨隆要塞所有建筑的控制权，并可学会从{altar}中训练{hero}");
    Add("Gain control of all buildings in Ny'lotha, learn to build the {mutationCircle}, and gain control of N'zoth", "获得尼奥罗萨所有建筑的控制权，学会建造{mutationCircle}，并获得恩佐斯的控制权");
    Add("Gain control of all units at Theramore", "获得塞拉摩所有单位的控制权");
    Add("Gain control of all units at Theramore and teleport all of your units within Dalaran to Theramore. Dalaran becomes hostile", "获得塞拉摩所有单位的控制权，并将你在达拉然境内的所有单位传送至塞拉摩。达拉然变为敌对");
    Add("Gain control of all units in Highmountain, and learn to train {unit}s from the {building}", "获得至高岭所有单位的控制权，并可学会从{building}训练{unit}");
    Add("Gain control of all units in Kul'tiras, gain control of Katherine Proudmoore, and acquire the {power} Power", "获得库尔提拉斯所有单位的控制权，获得凯瑟琳·普罗德摩尔的控制权，并获取{power}之力");
    Add("Gain control of all units in Stormwind, learn to train Varian from the {altar}, learn to cast {summonGarrison} from {keep}s and {castle}s, and acquire the {power} Power", "获得暴风城所有单位的控制权，学会从{altar}中训练瓦里安，学会从{keep}和{castle}施放{summonGarrison}，并获得「{power}」之力");
    Add("Gain control of all units in Tyr's Hand, learn to train Garithos from the {altar}, and learn to build {building}s", "获得提尔之手所有单位的控制权，学会从{altar}中训练加里索斯，并学会建造{building}");
    Add("Gain control of all units in the Capital City, gain Uther, and acquire the {power} Power", "获得都城所有单位的控制权，获得乌瑟尔，并获得{power}之力");
    Add("Gain control of all units in the Exodar and learn to train Nobundo from the {altar}", "获得埃索达所有单位的控制权，并学会从{altar}中训练努波顿");
    Add("Gain control of the Black Temple, learn to train Lady Vashj from the Altar of the Betrayer, abandon your base in the Broken Isles", "取得黑暗神殿的控制权，学会在背叛者祭坛中训练瓦丝琪女士，放弃你在破碎群岛的基地");
    Add("Gain control of the Draenei camp in Outland, learn to build {draeneiHut}s, and learn to train Akama from the {altar}", "取得外域德莱尼营地的控制权，学会建造 {draeneiHut}，并学会在 {altar} 训练阿卡玛");
    Add("Gain control of the Greymane Wall and Gilneas City. Enable to train Genn Greymane and the Worgen units.", "获得格雷迈恩之墙与吉尔尼斯城的控制权。解锁训练吉恩·格雷迈恩与狼人单位。");
    Add("Gain control of the Well of Eternity, which will grant every Sunfury unit unlimited mana", "获得永恒之井的控制权，这将使每个日怒单位都拥有无限的魔法值");
    Add("Gain control of the Zangarmarsh outpost, learn to build {clutchery}s, and learn to train Warlord Naj'entus from the {altar}", "取得赞加沼泽前哨的控制权，学会建造 {clutchery}，并学会在 {altar} 训练督军纳因图斯");
    Add("Gain control of the base in Shadowmoon Valley", "取得影月谷基地的控制权");
    Add("Gain control of the gate of Ahn'Qiraj", "获得安其拉大门的控制权");
    Add("Gain control of {place}, learn to train Falstad Wildhammer from the {altar}, and gain the ability to research {upgrade} at the {building}", "获得{place}的控制权，学会从{altar}中训练弗斯塔德·蛮锤，并获得在{building}研究{upgrade}的能力");
    Add("Gain control off all buildings in Feralas", "获得菲拉斯所有建筑的控制权");
    Add("Gain the Scepter of the Queen, the Athenaeum, 4 {highborne}, and the ability to train {highborne} from the {temple}", "获得女王权杖、图书馆、4 名{highborne}，并可在{temple}训练{highborne}");
    Add("Gain the ability to release Yogg-Saron from his near Storm peaks; he can be slain to acquire Val'anyr, Hammer of Ancient Kings", "获得在风暴峭壁附近释放尤格-萨隆的能力；将其击杀可获得瓦兰奈尔，远古王者之锤");
    Add("Gain vision over Lordaeron until you unleash the Plague, the Plague of Undeath research becomes available in the {building}, and {hero} becomes trainable at the {altar}", "在你释放瘟疫之前，获得洛丹伦的视野；{building}中将可研究亡灵瘟疫，且{hero}可在{altar}中训练");
    Add("Galecrash", "风碎");
    Add("Galen Trollbane has pledged his forces to Stormwind's cause.", "加林·托尔贝恩已宣誓将其军队投入暴风城的事业。");
