    Add("Gilaras Drakeson", "吉拉纳斯·达拉克森");
    Add("Gilneas Manor", "吉尔尼斯庄园");
    Add("Gilneas notcing our regained might in Southern-Lordaeron has decided to submit to our might to defend Lordaeron from the iminent Scourge invasion.", "吉尔尼斯目睹我们在洛丹伦南部重振雄威，已决定臣服于我们的力量，共同抵御迫在眉睫的天灾入侵。");
    Add("Gives gold to another player.", "将黄金赠予另一位玩家。");
    Add("Gloves of Ahn'qiraj", "安其拉护手");
    Add("God mod activated. Your units will deal 100x damage and take no damage.", "上帝模式已激活。你的单位将造成 100 倍伤害且不会受到伤害。");
    Add("God mode deactivated.", "上帝模式已关闭。");
    Add("Gogonnash", "戈古纳斯");
    Add("Good, let's get to it then.", "很好，那就动手吧。");
    Add("Gorehowl", "血吼");
