    Add("Gorrak Bloodcleaver", "戈拉克·裂血者");
    Add("Granis Darkhammer", "格兰尼斯·暗锤");
    Add("Grant Jaina Chaos Damage, 20 additional Intelligence, Teleport, and Mana Shield.", "赋予吉安娜混乱伤害、20 点额外智力、传送与法力护盾。");
    Add("Granted", "已获得");
    Add("Grants permanent vision over Northrend.", "永久获得诺森德的视野。");
    Add("Grants vision of all of Lordaeron's units.", "获得洛丹伦所有单位的视野。");
    Add("Great War (8v8)", "大战（8v8）");
    Add("Greetings, Prince Arthas. How fares your noble father?", "你好啊，阿尔萨斯王子。令尊近来可好？");
    Add("Grim Thunderbrew", "葛瑞姆·雷酒");
    Add("Grimnar Warblade", "格里姆纳·战刃");
    Add("Grommash Hellscream", "格罗玛什·地狱咆哮");
    Add("Grunt", "兽人步兵");
    Add("Gryphon Superior Breed", "狮鹫优良品种");
    Add("Gul'dan", "古尔丹");
    Add("Gul'dan's corpse in the Tomb of Sargeras", "萨格拉斯之墓中的古尔丹尸体");
    Add("Gul'dan's remains have been located within the Tomb of Sargeras. His eldritch knowledge may now be put to purpose.", "古尔丹的遗骸已在萨格拉斯之墓中被寻获。他那诡异的学识如今可为我们所用。");
    Add("HERO REWARD EARNED", "获得英雄奖励");
    Add("HERO SLAIN", "英雄阵亡");
    Add("HINT", "提示");
    Add("Hakkar", "哈卡");
    Add("Halahk the Lifebringer", "生命使者哈拉克");
    Add("Halduron Brightwing", "哈杜伦·明翼");
    Add("Hale Magefire", "哈尔·法师之焰");
    Add("Halendor Burnkin", "哈伦多·燃裔");
    Add("Hamuul Runetotem", "哈缪尔·符文图腾");
    Add("Hant", "安东尼达斯");
    Add("Harf", "阿尔萨斯·米奈希尔");
    Add("Harness the magical essence of Nordrassil to empower your forces and unlocks the {ability} for {unit}. The training limit of {djinn}'s and {efreet}'s is increased from 4 to 6", "汲取诺达希尔的魔法精华以强化你的部队，并为{unit}解锁{ability}。{djinn}与{efreet}的训练上限从 4 提高到 6");
    Add("Harrison Truewind", "哈里森·真风");
    Add("Have {hero} channel at {rect} for {duration} seconds", "让 {hero} 在 {rect} 引导 {duration} 秒");
    Add("Having failed to protect his people, Arthas seizes the cursed runeblade Frostmourne as the instrument of his vengeance. The malevolence of the blade overwhelms him. Arthas is now a loyal Death Knight of the Scourge, and will soon become its greatest champion.", "未能保护自己的人民，阿尔萨斯夺取了被诅咒的符文剑霜之哀伤，作为复仇的工具。剑中的邪恶吞噬了他。阿尔萨斯如今是天灾忠诚的死亡骑士，并将很快成为它最强大的勇士。");
    Add("He tells me that the time for my vengeance has come.", "他对我说，复仇的时候到了。");
    Add("Healing spellcaster.", "治疗型施法者。");
    Add("Hear me now, you trembling mortals! I am your lord and master! Illidan reigns supreme!", "都给我听好了，你们这些颤抖的凡人！我是你们的统治者和主人！我是至高无上的伊利丹！");
    Add("Hearthglen, finally! I could use some rest!", "终于到壁炉谷了！我可以休息一下了！");
    Add("Heavy range unit.", "重型远程单位。");
    Add("Hellfire Citadel", "地狱火堡垒");
    Add("Hello, Arthas.", "你好啊，阿尔萨斯。");
    Add("Helm of Domination", "统御之盔");
    Add("Herald to the Dark God N'zoth.", "黑暗之神恩佐斯的传令官。");
    Add("High Astromancer Solarion has long had a fascination with the void, much to the chagrin of her colleagues. With the right research materials in hand, she could become a force to be reckoned with.", "大星术师索兰莉安长久痴迷于虚空，令她的同僚颇为恼火。只要拿到合适的研究材料，她便能成为一股不可小觑的力量。");
    Add("High Templar Aurelian", "高阶圣殿骑士奥雷利安");
    Add("Hinterlands", "辛特兰");
    Add("Hjai", "吉安娜·普罗德摩尔");
    Add("Hkal", "凯尔萨斯·逐日者");
    Add("Hlgr", "加尔鲁什·地狱咆哮");
    Add("Hmbr", "穆拉丁·铜须");
    Add("Hmbr2", "穆拉丁·铜须");
    Add("Hogger and his pack have taken over Goldshire, clear them out!", "霍格与他的族群已经占据了闪金镇，把他们清除干净！");
    Add("Honor Hold is now free from the constant looming threat of Hellfire Citadel, and have finally been reconnected with their Alliance from Azeroth.", "荣誉堡如今摆脱了地狱火堡垒长久以来的威胁，终于与来自艾泽拉斯的联盟同胞重新取得了联系。");
    Add("Horgath Bloodmaw", "霍尔加斯·血颚");
    Add("Horrifying citadel of the Qiraji.", "其拉虫人可怖的堡垒。");
    Add("Hpb2", "瓦里安·乌瑞恩");
    Add("Huginn Ironcliff", "胡金·铁崖");
    Add("Hunting soldier of the Qiraji.", "其拉虫人的狩猎士兵。");
    Add("Huth", "光明使者乌瑟尔");
    Add("Hvsh", "瓦丝琪女士");
    Add("Hvwd", "希尔瓦娜斯·风行者");
    Add("I am Cairne, chief of the Bloodhoof tauren. You greenskins fight with both savagery and valor. I am intrigued.", "我是凯恩，血蹄牛头人的酋长。你们这些绿皮肤的战士充满了英勇和蛮劲。我很欣赏。");
    Add("I am Rexxar, last son of the Mok'Nathal.", "我是雷克萨，莫克纳萨最后的传人。");
    Add("I am Thrall, and these are my brethren, the orcs. We've come seeking the destiny promised to us.", "我是萨尔，他们都是我的兄弟。我们是兽人，来此寻找承诺中的命运。");
    Add("I am here to ensure that you do your job, little human. Not do it for you.", "我是来确保你不会玩忽职守的，渺小的人类。并不是来服侍你的。");
    Add("I am reborn, as promised! The Lich King has granted me eternal life!", "果然，我重生了！巫妖王赐予了我永生！");
    Add("I am still weak, and this reality is fading. I need to send my forces to all corners of the continent.", "我依旧虚弱，而这一现实正在消退。我需要将我的军队派往这片大陆的每一个角落。");
    Add("I don't know, but these creatures feel familiar somehow.", "不清楚，但他们总让我有种熟悉感的感觉。");
    Add("I have been scheming behind the backs of the other old gods  for eons, now my time has come. I will rule the world.", "万古以来，我一直在其他上古之神的背后暗中谋划，如今我的时代已经来临。我将统治这个世界。");
    Add("I have enslaved the cursed Tol'vir.", "我已奴役了受诅的托维尔人。");
    Add("I have found the Blade of the Black Empire.", "我找到了黑暗帝国之刃。");
    Add("I have gained a new Forgotten One.", "我获得了一个新的被忘却者。");
    Add("I have only recently awoken, wielding but a shadow of my might during the days of the Black Empire. I must reclaim my powers.", "我刚刚苏醒不久，所能施展的力量不过是黑暗帝国时代的一抹残影。我必须夺回我的力量。");
    Add("I have wandered alone for many years, little Misha. Yet sometimes, even I grow weary of this endless solitude.", "我已经独自游荡了许多年，小米莎。然而有时就连我也会厌倦这无尽的孤独。");
    Add("I have watched the other races. I have seen their squabbling, their ruthlessness. Their wars do nothing but scar the land and drive the wild things to extinction.", "我一直在观察着其他种族。我目睹了他们的争战不休、他们的冷酷无情。他们的战争让大地伤痕累累，让野生动物濒临灭绝。");
    Add("I knew it. Can we confirm our location? Is this Kalimdor?", "我知道了。能确认我们现在是在卡利姆多吗？");
    Add("I must admit, you orcs are more tenacious than I remembered. I thought you savages would have turned on each other by now.", "我必须承认，你们兽人比我记忆中的难缠多了。我以为你们这些野人早该自相残杀了。");
    Add("I suspected as much. These islands must have been formed only recently.", "我也觉得很奇怪。这些岛屿肯定是最近才出现的。");
    Add("I was wondering when you'd show up.", "我还在想你到哪去了呢。");
    Add("I was wrong to set you free, Illidan. I can see that now. You've become a monster.", "释放你是个错误，我终于看清楚了，伊利丹。你已经变成了一头怪物。");
    Add("I'll be happy to end your torment, old man. I told you that your magics could not stop me.", "那我很乐意能结束你的痛苦，老头。我说过，你的魔法阻止不了我。");
    Add("I'm through toying with you, night elf! Begone from my sight!", "我一直都在耍你，暗夜精灵！从我眼前消失吧！");
    Add("I've come to stop you, Illidan. Instead of banishing you, I should have returned you to your cage when I had the chance! I was weak then--but no longer.", "我是来阻止你的，伊利丹。当初真不该放逐你，我应该趁早把你关回牢里！都怪我那时心软——但现在不会了。");
    Add("Icecrown Glacier", "冰冠冰川");
    Add("Idioma cambiado a español.", "语言已切换为西班牙语。");
    Add("If Kel'thuzad dies, he revives in spectral form at Icecrown Citadel. Otherwise, he gains 4000 experience", "若克尔苏加德死亡，他将以幽灵形态在冰冠堡垒复活。否则，他将获得 4000 点经验值");
    Add("If you are a new player, look at the Quest (F9) tab to see your objectives.", "如果你是新玩家，请查看任务（F9）标签页以了解你的目标。");
    Add("If you have low FPS, try turning off your health bars.", "如果你的帧数较低，请尝试关闭生命值条。");
    Add("Illidan has failed to, or refused to, obey Kil'jaeden's command. For his disobedience, the Deceiver rips a portion of Illidan's power from his body, and turns his back to scheme elsewhere.", "伊利丹未能遵从，或拒绝遵从基尔加丹的命令。为惩罚他的忤逆，欺诈者从他体内撕下一部分力量，转身去别处谋划。");
    Add("Illidan has long thirsted for power, and no artifact can match the destructive energies of the Dark Titan's eye. Though far too powerful to be consumed in its entirety, merely possessing the artifact will unleash Illidan's true demonic potential.", "伊利丹长久以来渴求力量，而任何神器都无法与黑暗泰坦之眼的毁灭能量相提并论。它虽过于强大，无法被完整吞噬，但仅仅持有这件神器，便能释放出伊利丹真正的恶魔潜能。");
    Add("Illidan loses 5 Strength, Agility, and Intelligence", "伊利丹失去 5 点力量、敏捷与智力");
    Add("Illidan maintains an unquenchable thirst for power. The Skull of Gul'dan, the Warglaives of Azzinoth - these artifacts are not enough. He demands more.", "伊利丹对力量的渴求永无止境。古尔丹之颅、埃辛诺斯战刃——这些神器还远远不够。他索求更多。");
    Add("Illidan pores over the prophet's tome, unveiling arcane secrets that enhance his already prodigious mastery over magic.", "伊利丹潜心研读先知的书典，揭开了奥术的秘密，使他本已超凡的魔法造诣更上层楼。");
    Add("Illidan returns triumphant to Black Temple, the seat of his power. The orcs and demons of Outland hail his coming.", "伊利丹凯旋返回黑暗神殿——他权力的王座。外域的兽人与恶魔齐声欢呼他的归来。");
    Add("Illidan stole three vials from the Well of Eternity. He used one to create a new Well beneath Nordrassil, and kept the other two hidden - but one went missing.", "伊利丹从永恒之井中窃取了三瓶井水。他用其中一瓶在诺达希尔之下创造了新的水井，另两瓶则被藏了起来——但有一瓶不知所踪。");
    Add("Illidan's Metamorphosis becomes permanent", "伊利丹的恶魔变形变为永久效果");
    Add("Illidan's servants in Outland have been left to their own devices for too long; he must return swiftly if he is to prepare them for the coming war.", "伊利丹留在外域的仆从已经太久无人管束；若想让他们为即将到来的战争做好准备，他必须迅速返回。");
    Add("Illidari", "伊利达雷");
    Add("Immortality", "永生");
    Add("Improves Dreadlords and Nathrezim by increasing their attack damage by 20, movement speed by 20, hit points by 200, improves the Vampiric Siphon ability and grants them the ability to cast Astral Walk", "强化恐惧魔王与纳斯雷兹姆，使其攻击伤害提高 20、移动速度提高 20、生命值提高 200，强化吸血虹吸技能，并赋予他们施放星界行走的能力");
    Add("In a rare twist of fate, the Lich King's prophecy did not come to pass: Kel'thuzad survived long enough to reach the Sunwell under his own power.", "命运难得地出现了转折，巫妖王的预言并未成真：克尔苏加德凭自身力量撑到了太阳之井。");
    Add("In an act of fratricide, Illidan has defeated the Legion's ancient enemies and seized Nordrassil for Kil'jaeden. The Deceiver upholds his end of the bargain, and bestows unto the Illidari his gift.", "伊利丹以弑兄之举击败了军团的宿敌，并为基尔加丹夺下了诺达希尔。欺诈者履行了他的承诺，将他的馈赠赐予伊利达雷。");
    Add("In millenia past, the most vile entities of Azeroth were imprisoned in a facility near Zin-Ashari, but it was abandoned when the Broken Isles were shattered. In troubling times such as these, the Wardens could make great use of such a facility.", "数千年前，艾泽拉斯最邪恶的存在曾被囚禁在辛艾萨莉附近的一处设施中，但破碎群岛分崩离析后，此地便被废弃。值此多事之秋，守望者正可善加利用这样的设施。");
    Add("In the Dream, I felt our land being corrupted, just as if it were my own body. You were right to awaken me.", "在梦中，我感到腐化正在的大地上蔓延，如同正在腐化我的身体。唤醒我是正确的。");
    Add("In the ashes of the battle of Black Temple, the Fel Horde will rebuild their bases of operation to support their new overlord", "在黑暗神殿之战的灰烬中，邪部落将重建他们的行动基地，以支援他们的新霸主。");
    Add("Infernalash", "狱烬");
    Add("Infinite mana activated.", "无限法力已激活。");
    Add("Infinite mana deactivated.", "无限法力已关闭。");
    Add("Inquisitor Varrus Holycinder", "审判官瓦鲁斯·圣烬");
    Add("Instant build activated.", "瞬间建造已激活。");
    Add("Instant build deactivated.", "瞬间建造已关闭。");
    Add("Intelligence", "智力");
    Add("Invaders from Azeroth have taken control of the Twilight landing. Destroy them!", "来自艾泽拉斯的入侵者已控制了暮光登陆场。消灭他们！");
    Add("Invalid input. Use 'on', 'off', 'true', or 'false'.", "输入无效。请使用 'on'、'off'、'true' 或 'false'。");
    Add("Invalid parameter used.", "使用了无效的参数。");
    Add("Invalid parameter. Please use 'en'/'english' or 'es'/'espanol'.", "参数无效。请使用 'zh'/'zhcn'、'en'/'english' 或 'es'/'espanol'。");
    Add("Invalid parameter. Please use 'true', 'false', 'on', or 'off'.", "参数无效。请使用 'true'、'false'、'on' 或 'off'。");
    Add("Invalid parameter. Please use a number between 700 and 2701, or one of the presets: 'near', 'medium', 'far'.", "参数无效。请输入 700 至 2701 之间的数值，或使用预设：'near'、'medium'、'far'。");
    Add("Is talking all you demons do?", "你们恶魔就只会讲大话吗？");
    Add("It has been a thousand years since I last looked up you, Tyrande. I thought of you every moment I roamed through the Emerald Dream.", "已经一千年没有见到你的样子了，泰兰德。在翡翠梦境中漫步时，我每时每刻都在想念着你。");
    Add("It is I, Kel'Thuzad. I was right about you, Prince Arthas.", "是我，克尔苏加德。我就在你身边，阿尔萨斯王子。");
    Add("It is a father's right to dream, isn't it?", "当父亲的总是会望子成龙的嘛。");
    Add("It is you who should turn back, Sylvanas. Death itself has come for your land.", "该滚回去的是你，希尔瓦娜斯。死神已经亲临你的王国。");
    Add("It pains me to even look at you, Arthas.", "看到你真让我难受，阿尔萨斯。");
    Add("It seems Ner'zhul is finally free from his tortured existence as the bearer of the Helm of Domination.", "看来耐奥祖终于从作为统御之盔载体的痛苦存在中解脱了。");
    Add("Jaina Proudmoore abandons the once mighty city of Dalaran and leads her people across the sea, arriving in the untamed lands of Kalimdor.", "吉安娜·普罗德摩尔放弃了昔日强盛的达拉然城，带领她的人民渡海西行，抵达卡利姆多这片未驯之地。");
    Add("Jaina Proudmoore has discovered the Soul Gem within the ruined vaults at Scholomance.", "吉安娜·普罗德摩尔在通灵学院残破的地窖中发现了灵魂宝石。");
    Add("Jeremiah Wavecaller", "杰里迈亚·唤潮者");
    Add("Join our Discord:", "加入我们的 Discord：");
    Add("Jorn the Redeemer", "救赎者乔恩");
    Add("Justicar Thalos Redmark", "裁决者塔洛斯·红痕");
    Add("Kael'thas' profane ritual has paved the way for Kil'jaeden, supreme commander of the Burning Legion, to bridge the gap from the Twisting Nether to our world. Our people embrace fel magic wholeheartedly, training in preparation for their coming lord.", "凯尔萨斯的亵渎仪式已为燃烧军团最高指挥官基尔加丹铺平道路，让他得以从扭曲虚空跨越裂隙降临我们的世界。我们的人民全心拥抱邪能魔法，日夜操练，迎接即将到来的主人。");
    Add("Kaelvinar Sunward", "凯尔维纳·向日");
    Add("Kaelvros Nightbane", "凯尔弗罗斯·夜祸");
    Add("Kag'ar Winterfang", "卡伽尔·冬牙");
    Add("Kali'naj Dethknell", "卡里那吉·丧钟");
    Add("Karazhan has been captured. Dalaran's archivists scour its halls for arcane resources.", "卡拉赞已被占领。达拉然的档案员们翻遍其厅堂，搜寻奥术资源。");
    Add("Kargath Ironfist", "卡加斯·铁拳");
    Add("Karnwield the Seeker", "求知者卡恩维尔德");
    Add("Kath'ranis Remar", "卡兹拉尼斯·雷玛");
    Add("Kathris Starsong", "卡瑟蕊丝·星歌");
    Add("Kazil Darkeye", "卡兹尔·黑眼");
    Add("Kazragore", "卡兹拉戈");
    Add("Keep", "要塞");
    Add("Keg of Thunderwater", "雷霆之水酒桶");
    Add("Kel'Thuzad", "克尔苏加德");
    Add("Kel'thuzad is the leader of the Cult of the Damned and an extraordinarily powerful necromancer. If he were to be brought to the Sunwell and submerged in its waters, he would be reanimated as an immortal Lich.", "克尔苏加德是诅咒教派的领袖，也是一位极其强大的通灵师。若将他带到太阳之井并浸入其水中，他将被复活为不朽的巫妖。");
    Add("Kelen the Destroyer", "毁灭者凯伦");
    Add("Kelv Sternhammer", "凯夫·重锤");
    Add("Kera Stardragon", "凯拉·星蛟");
    Add("Khadgar has been freed from his confines under the Black Temple, and he is now free to serve the Kingdom of Stormwind.", "卡德加已从黑暗神殿之下的囚禁中获释，如今他可以自由地为暴风王国效力了。");
    Add("Khadgar has sealed the Dark Portal forever, finally correcting the mistake made by his former master decades ago.", "卡德加已永久封印黑暗之门，终于弥补了数十年前他恩师所犯下的过错。");
    Add("Kil'jaeden has reformed the ancient Well of Eternity. From its wellsprings, unlimited arcane energies spring forth. For the first time in their miserable existences, the Sunfury are truly sated.", "基尔加丹已重塑古老的永恒之井。无尽的奥术能量自其源泉中喷涌而出。日怒们悲惨的一生中，第一次真正得到了满足。");
    Add("Kil'jaeden the Deceiver has been annihilated, but it is too late for the Sunfury, who will continue to live and die with demonic taint coursing through their veins.", "欺诈者基尔加丹已被消灭，但对日怒来说为时已晚——他们体内的恶魔邪能将继续奔流，直至生老病死。");
    Add("Kil'jaeden's Cunning", "基尔加丹的狡诈");
    Add("Kill Sapphiron the Blue Dragon to have Kel'Thuzad reanimate her as a Frost Wyrm. Sapphiron can be found in Northrend.", "杀死蓝龙萨菲隆，让克尔苏加德将其复活为冰霜巨龙。萨菲隆可在诺森德找到。");
    Add("Kill {required} non-summoned enemy units ({current}/{required})", "击杀 {required} 个非召唤的敌方单位（{current}/{required}）");
    Add("Kilsorrow Fortress has been razed.", "基尔索罗堡垒已被夷为平地。");
    Add("King Emeritus Terenas Menethil", "荣休国王泰瑞纳斯·米奈希尔");
    Add("King Magni Bronzebeard has died.", "国王麦格尼·铜须已经逝世。");
    Add("Kingdom of Gilneas", "吉尔尼斯王国");
    Add("Kingdom of Ironforge", "铁炉堡王国");
    Add("Kingdom of Kul Tiras", "库尔提拉斯王国");
    Add("Kingdom of Lordaeron", "洛丹伦王国");
    Add("Kingdom of Quel'Thalas", "奎尔萨拉斯王国");
    Add("Kingdom of Stormwind", "暴风王国");
    Add("Knowledge:", "知识：");
    Add("Korvak the Butcher", "屠夫科尔瓦克");
    Add("Korvath Steelpaw", "科尔瓦斯·钢掌");
    Add("Krag Deathshroud", "克拉格·死亡之幕");
    Add("Kranix the Armored", "披甲者克兰尼克斯");
    Add("Krasus", "克拉苏斯");
    Add("Kryptikk Soulslayer", "克瑞普提克·屠魂者");
    Add("Krythos the Silkbound", "缚丝者克里斯托斯");
    Add("Kul Tiras has degenerated severely in contemporary times. Bandits and vile monsters threaten the islands and the noble houses have split apart. We must quell these threats and reunite the kingdom's various regions under Daelin Proudmoore's command.", "如今的库尔提拉斯已严重衰败。盗匪与邪恶的怪物威胁着各座岛屿，贵族家族也已分崩离析。我们必须平定这些威胁，并在戴林·普罗德摩尔的统领下重新统一王国的各个地区。");
    Add("Kul Tiras' historical isolationism has allowed piracy to fester throughout the seas. It's high time that we do something about it; we can start with the Goblin freebooters living it up in Booty Bay.", "库尔提拉斯历来奉行孤立主义，任由海盗在各处海域滋生蔓延。是时候采取行动了；我们可以从藏宝海湾里逍遥度日的地精海盗下手。");
    Add("Kurdran Wildhammer", "库德兰·蛮锤");
    Add("LEGENDARY FOE SLAIN", "传奇敌人已被击杀");
    Add("LEGENDARY FOE SUMMONED", "传奇敌人已被召唤");
    Add("LOOK UPON YOGG-SARON, GOD OF DEATH, AND KNOW THAT YOUR END COMES SOON!", "对死亡之神尤格-萨隆致敬吧，要知道你的末日也为时不远了！");
    Add("Lady Snakemane", "蛇鬃女士");
    Add("Lady Vashj and her Naga were instrumental in securing Outland, and for their deeds received the swamp of Zangarmarsh. It has become overrun in recent times, and must be reclaimed if the Naga are to aid in the fight against the Alliance.", "瓦丝琪女士与她的纳迦在夺取外域的过程中居功至伟，因此获赐赞加沼泽。近来此地已被侵占，若纳迦要协助对抗联盟，就必须将其夺回。");
    Add("Lady Venomtongue", "毒舌女士");
    Add("Language changed to English.", "语言已切换为英语。");
    Add("Larodar", "拉罗达");
    Add("Learn to build the Divine Bastion", "学会建造神圣堡垒");
    Add("Learn to build {chapterHouse}s, and learn to train Meredith Waycrest from the {altar}", "学会建造{chapterHouse}，并学会从{altar}中训练梅瑞狄斯·维克雷斯");
    Add("Learn to cast Frost Nova and Animate Dead from the Frozen Throne", "学会从冰封王座施放冰霜新星与亡者再临");
    Add("Learn to research three powerful upgrades at Karazhan.", "学会在卡拉赞研究三项强大的升级。");
    Add("Learn to research {upgrade} from the {building}", "学会从{building}研究{upgrade}");
    Add("Learn to train Alexandros Mograine from the {altar}", "学会从{altar}中训练亚历山德罗斯·莫格莱尼");
    Add("Learn to train Blue Dragons", "学会训练蓝龙");
    Add("Learn to train Darius Crowley from the {altar}", "学会从{altar}中训练达利乌斯·克罗雷");
    Add("Learn to train High Astromancer Solarion from the {altar}", "学会从{altar}中训练大星术师索兰莉安");
    Add("Learn to train Kil'jaeden from the {altar}, and {warlock}s from the {lyceum}", "学会从{altar}中训练基尔加丹，并从{lyceum}训练{warlock}");
    Add("Learn to train Maiev Shadowsong from the {altar} and gain control of the survivors hiding in Feathermoon.", "学会从{altar}中训练玛维·影歌，并获得藏身于羽月要塞的幸存者的控制权。");
    Add("Learn to train Neptulon from the {altar}, Tidal Lords from the {building}, and unlocks the {ability} for {unit}.", "学会从{altar}中训练耐普图隆、从{building}训练潮汐领主，并为{unit}解锁{ability}。");
    Add("Learn to train Ragnaros from the {altar} and learn to build the Magma Complex", "学会从{altar}中训练拉格纳罗斯，并学会建造熔岩建筑群");
    Add("Learn to train Sally Whitemane from the {altar}", "学会从{altar}中训练萨莉·怀特迈恩");
    Add("Learn to train Warlord Zon'ozz from the {altar}", "学会从{altar}中训练督军佐诺兹");
    Add("Learn to train one additional {forgottenOne} from the {mutationCircle}", "学会从{mutationCircle}额外训练 1 个{forgottenOne}");
    Add("Learn to train troops from Shadowfang Keep.", "学会从影牙城堡训练部队。");
    Add("Learn to train troops from the Monastery.", "学会从修道院训练部队。");
    Add("Learn to train troops from the Spire Keep and gain 500 gold", "学会从风行者要塞训练部队，并获得 500 黄金");
    Add("Learn to train {aqir}s from the {pitOfTorment}", "学会从{pitOfTorment}训练{aqir}");
    Add("Learn to train {count} {unit}s from the {building} and acquire Felsteel Plating", "学会从{building}训练{count}个{unit}，并获得魔钢装甲");
    Add("Learn to train {eradicator}s from the {hatchery}, learn to train {tolvirStatue}s from the {pyramid} and learn to train Moam from the {altar}", "学会从{hatchery}训练{eradicator}，学会从{pyramid}训练{tolvirStatue}，并学会从{altar}中训练莫阿姆");
    Add("Learn to train {hero} from the {altar}, and learn to train {unit} from the {building}. If you're allied to the Druids, {hero}'s starting experience is halved", "学会从{altar}中训练{hero}，并学会从{building}训练{unit}。若你与德鲁伊结盟，{hero}的初始经验值减半");
    Add("Learn to train {moonRider}s from the {roost}s and research {upgrade}'s second level from the {academy}", "学会从{roost}训练{moonRider}，并在{academy}研究{upgrade}的第二级");
    Add("Learn to train {sandWorm}s from the {altar}", "学会从{altar}中训练{sandWorm}");
    Add("Learn to train {unit}s", "学会训练{unit}");
    Add("Learn to train {unit}s from the {building}", "学会从{building}训练{unit}");
    Add("Learn to train {unit}s from the {building}, and you can summon Magister Rommath & Lor'themar Theron from the {altar}", "学会从{building}训练{unit}，并可从{altar}召唤大魔导师罗曼斯与洛瑟玛·塞隆");
    Add("Learn to train {unit}s from the {building}. If your team killed Sapphiron, gain him in an undead form; otherwise, learn to train him from the {altar}", "学会从{building}训练{unit}。若你的队伍击杀了萨菲隆，你将获得亡灵形态的他；否则，可学会从{altar}中训练他");
    Add("Legion Summon", "召唤军团");
    Add("Leios Sunward", "莱奥斯·向日");
    Add("Let's see how confident you are against one of your own kind, dreadlord!", "来看看你面对自己的同类时能有多自信吧，恐惧魔王！");
    Add("Level of research", "研发等级");
    Add("Liberation of Gilneas", "解放吉尔尼斯");
    Add("Lighthouse", "灯塔");
    Add("Lightning Attack", "闪电攻击");
    Add("Long Range flying Horrors.", "远程飞行的恐怖之物。");
    Add("Long ago, Fandral Staghelm cut a sapling from Nordrassil and used it to grow Andrassil in Northrend. Without the blessing of the Aspects, it fell to the Old Gods' corruption. If Northrend were to be reclaimed, Andrassil's growth could begin anew.", "很久以前，范达尔·鹿盔从诺达希尔上切下一株幼苗，用以在诺森德种下安达希尔。由于缺少守护巨龙的祝福，它最终沦陷于上古之神的腐蚀。若能收复诺森德，安达希尔便有可能重新生长。");
    Add("Long ago, the Night Elves' hubris led them to forge a second Well of Eternity following the destruction of the first. Nordrassil was planted atop it as a means of protection, but this measly act of defiance shall not prevent Lord Archimonde from seizing the Well's energies for himself.", "很久以前，暗夜精灵的狂妄驱使他们在第一口永恒之井被毁后，又造就了第二口。诺达希尔被种于其上作为守护，但这微不足道的反抗之举，绝无法阻止阿克蒙德领主将井中的能量据为己有。");
    Add("Long ago, the orcs drank the blood of Mannoroth and were infused with demonic fury. A mere taste of his blood would reignite those powers.", "很久以前，兽人饮下了玛诺洛斯之血，被注入了恶魔的狂怒。只需尝到一口他的鲜血，那股力量便会再度燃起。");
    Add("Long-range siege weaponry. Effective against buildings but slow and vulnerable.", "|cff2fc6ba攻城 单位|r");
    Add("Look, mistress--more of Gul'dan's glyphs.", "瞧，女主人——还是古尔丹的符文。");
    Add("Looks like you haven't lost your touch. It's good to see you again, Jaina.", "看来你的身手还是不减当年啊。真高兴与你重逢，吉安娜。");
    Add("Lorandis Faithhammer", "罗兰迪斯·信仰之锤");
    Add("Lord Antonidas. There's no need to be snide.", "安东尼达斯大人。风凉话就放一边吧。");
    Add("Lord Darkhallow", "达克哈罗勋爵");
