    Add("Lordaeron City was once the heart of the Alliance and the center of the humanity before its fall. It must be reclaimed at all costs.", "洛丹伦城在陷落之前曾是联盟的心脏、人类世界的中心。必须不惜一切代价将其夺回。");
    Add("Lordaeron has been destroyed by the vile Scourge, leaving those left alive with naught but vengeance in their hearts. From the ashes rises the Scarlet Crusade, the untempered bright that will bring to the undying dead the wrath of the living.", "洛丹伦已被邪恶的天灾摧毁，幸存者心中只剩下复仇。血色十字军自灰烬中崛起——那未经淬炼的光辉，将把生者的怒火带给不死的亡者。");
    Add("Lordaeron is destined to fall to the Scourge. Should such an event come to pass, the Silver Hand will be transformed beyond recognition, abandoning ideals of justice in favour of those of vengeance.", "洛丹伦注定要陷落于天灾。倘若此事成真，白银之手将变得面目全非，抛弃正义的理想，转而信奉复仇。");
