    Add("Magtheridon’s eternal demon soul has been consumed, and his life permanently extinguished. The Lord of Outland has fallen.", "玛瑟里顿不灭的恶魔灵魂已被吞噬，他的生命被永久终结。外域之主已经陨落。");
    Add("Maiev drive for vengeance leads her to chase Illidan all the way to other worlds.", "玛维的复仇之念驱策她一路追杀伊利丹，直至异界。");
    Add("Maiev's Outland outpost have been constructed.", "玛维的外域前哨站已经建成。");
