    Add("Mal'Ganis", "玛尔加尼斯");
    Add("Mal'ganis' citadel lies somewhere within the arctic wastes of the north. In order to assault the Dreadlord, Arthas must first establish a base camp at the shores of Northrend.", "玛尔加尼斯的堡垒位于北方极地荒原的某处。要进攻这位恐惧魔王，阿尔萨斯必须先在诺森德海岸建立营地。");
