    Add("Medivh's body was corrupted by Sargeras at conception. Now that he is dead, the secrets of the Tomb of Sargeras and Karazhan combined might allow the mages of Dalaran to cleanse his spirit.", "麦迪文尚在母胎之中时，其肉身便被萨格拉斯腐化。如今他已死去，若能结合萨格拉斯之墓与卡拉赞的秘密，达拉然的法师们或许可以净化他的灵魂。");
    Add("Medivh's death left Azeroth without a Guardian. The spell book he left behind could be used to empower a new one.", "麦迪文之死让艾泽拉斯失去了守护者。他留下的法术书可以用来赋予一位新的守护者力量。");
    Add("Medivh's spirit has been cleansed of Sargeras' influence, allowing him to return to Azeroth for a time.", "麦迪文的灵魂已摆脱萨格拉斯的影响得到净化，这让他得以暂时重返艾泽拉斯。");
    Add("Mere months ago, Thrall's forces saved the Darkspear tribe from the brink of extinction at the hands of constant murloc raids. They have recently made a new home on the Echo Isles, and could prove formidable allies in the invasion of Kalimdor.", "就在几个月前，萨尔的部队将暗矛部族从鱼人不断袭击所带来的灭绝边缘拯救了出来。他们最近在回音群岛建立了新的家园，在入侵卡利姆多时将成为强大的盟友。");
    Add("Miasmus", "米亚斯穆斯");
