    Add("Mount Hyjal has been invaded by the corruption already affecting Felwood. Clear them out to awaken the Ancients", "海加尔山已被那早已侵蚀费伍德森林的腐化入侵。清剿它们，唤醒上古守护者");
    Add("Moved all Zin'rokh fragments to the currently selected unit.", "已将全部辛洛斯碎片移至当前选中的单位身边。");
