    Add("Muradin Bronzebeard", "穆拉丁·铜须");
    Add("My Qiraji have ripped, torn, and consumed scores of fallen prey, satiating their hunger and lifting a bloody haze from my mind.", "我的其拉虫人撕碎、扯裂并吞噬了数十具倒下的猎物，满足了它们的饥渴，也让我脑海中的血雾渐渐消散。");
    Add("My heart rejoices to see you again, Furion. But I would not have awakened you unless the need was urgent.", "再次见到你也让我的心中充满了欢喜，玛法里奥。但若非事态危急，我绝不会轻易将你唤醒。");
    Add("My influence must spread further and further, bringing Nyalotha into this reality and making me ever stronger", "我的影响必须不断扩散，将尼奥罗萨带入这一现实，让我愈发强大");
    Add("My singular gaze opens wide, pouring into the minds of all those unfortunate enough to inhabit Azeroth during my imminent reign.", "我独一的凝视将彻底睁开，灌入每一个不幸在我即将降临的统治期间居于艾泽拉斯之人的心智。");
    Add("Myrieth Dawnshield", "米莉丝·黎明之盾");
