    Add("No, they cannot be trusted. Only beasts are above deceit.", "不，我信不过他们。只有野兽才不会欺骗。");
    Add("Nobody had noticed, but until now Renault has been somewhat reserved in his actions. With his hometown now reclaimed, he shines with a new vigour.", "无人察觉，但直到此刻，雷诺在行动中都颇为内敛。如今故乡已被收复，他焕发出全新的活力。");
    Add("Nobody is playing", "没有玩家正在扮演");
    Add("Nordrassil has been taken, and with it, the source of the Night Elves' immortality. The War of the Shifting Sands, begun anew a thousand years after its first conclusion, is over once more.", "诺达希尔已被夺取，暗夜精灵永生的根源也随之落入我手。首次流沙之战结束千年之后重燃的战火，再度平息。");
    Add("Nordrassil, the World Tree, stands as a bastion of life and balance. By conquering it, Skywall can assert dominion and tip the scales of power.", "世界之树诺达希尔是生命与平衡的堡垒。征服它，天空之墙便能确立统治，扭转力量的天平。");
    Add("Northern Ashenvale", "北灰谷");
    Add("Northrend Expedition", "诺森德远征");
    Add("Northrend and the Icecrown Citadel is now under full control of the Lich King and the Scourge.", "诺森德与冰冠堡垒如今已完全落入巫妖王与天灾军团的掌控之中。");
    Add("Northrend quakes as Icecrown Citadel topples to the glacier below, bringing a final end to Ner'zhul's fortress and prison of ice.", "冰冠堡垒轰然倾塌，坠向下方冰川，诺森德为之震颤——耐奥祖的堡垒与寒冰牢笼就此彻底终结。");
    Add("Now I am complete!", "啊，如此强大的力量！");
    Add("Now, arise, Kel'Thuzad, and serve the Lich King once again!", "现在，复活吧，克尔苏加德，再一次侍奉巫妖王！");
    Add("Now, at long last, I have returned to set things right. I... am Medivh, the Last Guardian. I tell you now, the only chance for this world is for you to unite in arms against the enemies of all who live!", "如今，我终于回来了，为了能弥补昔日的过错。我是麦迪文……最后的守护者。听我说，你们必须齐心协力对抗众生之敌，这是整个世界最后的希望了！");
