    Add("Once protectors of the Emerald Dream, the now corrupted dragons came to Azeroth to spread the corruption. Stop them before the corruption begins to spread.", "这些巨龙曾是翡翠梦境的守护者，如今却已被腐化，来到艾泽拉斯散播腐化。在他们将腐化扩散开来之前阻止他们。");
    Add("Once the breadbasket of Lordaeron, Andorhal is now nothing but ashes. Were it to be rebuilt, its proximity to Aerie Peak would allow the Scarlet Crusade to breed powerful Eagles and Gryphons.", "安多哈尔曾是洛丹伦的粮仓，如今只剩下灰烬。若能重建，它毗邻鹰巢山的地理位置将让血色十字军得以繁育强壮的雄鹰与狮鹫。");
    Add("Only recently awoken from their long slumber, my Qiraji are ravenous for flesh.", "我的其拉虫人刚从漫长的沉睡中苏醒不久，正渴求着血肉。");
    Add("Onyxia", "奥妮克希亚");
    Add("Open Alliance", "开放同盟");
    Add("Open a Portal between Tempest Keep and Argus", "在风暴要塞与阿古斯之间开启一道传送门");
    Add("Open a one-way portal to Black Temple", "开启一道通往黑暗神殿的单向传送门");
