    Add("Orex", "雷克萨");
    Add("Orgrimmar has been demolished and with it die the hopes and dreams of a wartorn race seeking refuge in a new world.", "奥格瑞玛已被摧毁，一个饱经战乱、在新世界中寻求庇护的种族的希望与梦想也随之破灭。");
    Add("Orithal Sunblade", "奥里萨尔·日刃");
