    Add("Queen Azshara studied many forms of arcane knowledge, some darker than others. With access to her library and enough time, I will uncover her secrets.", "艾萨拉女王研究过许多形式的奥术知识，其中有些比另一些更为黑暗。只要能进入她的书库并有足够的时间，我就能揭开她的秘密。");
    Add("Queen Azshara studied many forms of arcane knowledge, some darker than others. With access to her library and enough time, the highborn scholares could uncover her secrets", "艾萨拉女王研究过许多形式的奥术知识，其中一些比另一些更为黑暗。若能进入她的书库并有足够的时间，上层精灵学者们或许能揭开她的秘密");
    Add("Quel'danil Lodge is a High Elven outpost situated in the Hinterlands. It's been some time since the rangers there have been in contact with Quel'thalas.", "奎尔丹尼小屋是位于辛特兰的一处高等精灵前哨。那里的游侠已有些时日未与奎尔萨拉斯联络了。");
