    Add("Ragnaros and the Firelands will join the Old Gods, we need to make contact with them.", "拉格纳罗斯与火焰之地将加入上古之神一方，我们必须与他们取得联系。");
    Add("Ragnaros hides within the Elemental Plane known as the Firelands. Outside Shadowforge City, the Dark Iron dwarves have been trying to summon him forth into Azeroth. Their efforts until now have proved ineffective, but we could succeed where they have not.", "拉格纳罗斯藏身于名为火焰之地的元素位面。在暗炉城外，黑铁矮人一直试图将他召唤到艾泽拉斯。他们的努力至今徒劳无功，但我们或许能做成他们做不到的事。");
    Add("Ragnaros is summoned near the Blackrock Depths, and can be slain to acquire Sulfuras", "拉格纳罗斯被召唤至黑石深渊附近，将其击杀可获得萨弗拉斯");
    Add("Ragnaros, the Elemental Lord of Fire, has been forcibly called forth into Azeroth. The air smolders with his arrival, and Blackrock Mountain erupts in raging infernos that can be seen for miles.", "火元素领主拉格纳罗斯被强行召唤至艾泽拉斯。他的降临令空气灼烧，黑石山爆发出冲天烈焰，数里之外清晰可见。");
