    Add("Rexxar ventures north into lands once thought incompatible with life, and discovers the paradise of furred megafauna that is the Borean Tundra. He tames the woolly mammoths there, and teaches the Frostwolf to ride them into battle.", "雷克萨一路北上，踏入那片曾被认为不适合生命存续的土地，并发现了北风苔原这处长满毛皮巨兽的天堂。他在那里驯服了长毛猛犸象，并教会霜狼氏族骑乘它们投入战斗。");
    Add("Rexxar's wanderlust has brought him into contact with all kinds of beasts. Yet there is one major landmass he has never ventured to: the cold expanse of Northrend. Surely the wild things roam free even there.", "雷克萨的漫游癖好让他接触过各种各样的野兽。然而还有一片大陆他从未涉足：诺森德那片寒冷的广袤之地。想必即便是那里，野兽也照样自由徜徉。");
