    Add("Several small armies under your control spawn throughout Lordaeron, you gain control of three bases around Lordaeron, Lordaeron's Control Points reset to level 0, and you will be given a choice to instantly move your military units from Northrend to one of three locations in Lordaeron", "数支由你控制的小型军队会在洛丹伦各地出现，你获得洛丹伦周边三座基地的控制权，洛丹伦的控制点重置为 0 级，并且你将可以选择将你的军事单位从诺森德立即转移到洛丹伦的三个地点之一");
    Add("Shadowfang Keep is now under the Legion control. A secret demon gate has now been formed inside.", "影牙城堡现已落入军团的掌控。一道秘密的恶魔之门如今已在其中成形。");
