    Add("Sten Azureshield", "斯滕·碧蓝之盾");
    Add("Stonefury", "石怒");
    Add("Stonetalon Peak", "石爪峰");
    Add("Storm Peaks", "风暴峭壁");
    Add("Stormbark", "风暴树皮");
    Add("Stormwind Keep", "暴风要塞");
    Add("Stormwind Keep, the capitol of the nation of Stormwind, has been destroyed!", "暴风要塞——暴风王国的都城——已被摧毁！");
    Add("Stormwind and Ironforge lie shattered, their armies broken before they could reach the heart of Outland. With the Alliance in ruin, the Illidari have secured their future.", "暴风城与铁炉堡已化为废墟，他们的军队尚未抵达外域腹地便已被击溃。联盟既已崩毁，伊利达雷便已确保了自己的未来。");
    Add("Stormwind faces the threat of annihilation at the hands of forces from beyond the Dark Portal, and they have called in our assistance. If we are to aid them, we must first establish a foothold on Stranglethorn's coast.", "暴风城正面临来自穿越黑暗之门大军的毁灭威胁，他们已向我们求援。若要驰援他们，我们必须先在荆棘谷的海岸上建立立足点。");
    Add("Stormwind has not yet fully recovered from the ravaging it experienced during the Second War. Await reconstruction.", "暴风城尚未从第二次大战的蹂躏中完全恢复。静候重建。");
    Add("Stormwind's Construction Sites are now ready to be upgraded.", "暴风城的建筑工地现在可以升级了。");
    Add("Stormwind's annihilation has left behind the corpses of thousands of elite knights. As occurred during the Second War, these corpses have been filled with the souls of slain Shadow Council members, recreating the indominatable order of Death Knights.", "暴风城的覆灭留下了数以千计精锐骑士的尸骸。正如第二次大战时那样，这些尸骸已被灌入陨落暗影议会成员的灵魂，重现了那支无可阻挡的死亡骑士团。");
    Add("Stratholme Castle", "斯坦索姆城堡");
    Add("Strength", "力量");
    Add("Strong support spellcaster of the Horde.", "部落强大的支援型施法者。");
    Add("Strongest Silithid.", "最强的异种蝎。");
    Add("Subdue the Ogres", "驯服食人魔");
    Add("Subdue the Tauren", "驯服牛头人");
    Add("Subdue the Trolls", "驯服巨魔");
    Add("Successfully changed faction to", "已成功将阵营切换为");
    Add("Sulfiren Bonewrought", "苏尔菲伦·骨锻");
    Add("Sulfuras, Hand of Ragnaros", "萨弗拉斯，炎魔拉格纳罗斯之手");
    Add("Summoned units grant no experience when slain.", "召唤出来的单位被击杀时不会提供经验值。");
    Add("Summoner", "召唤师");
    Add("Summoning Kil'jaeden", "召唤基尔加丹");
    Add("Sunken Temple", "沉没的神庙");
    Add("Support", "支援");
    Add("Support spellcaster.", "支援型施法者。");
    Add("Supremely deadly Warrior Hero, Excels at killing enemy Heroes.", "极其致命的战斗型英雄，擅长击杀敌方英雄。");
    Add("Surviving forces retreat to Durotar at reduced health", "幸存的部队以降低后的生命值撤退至杜隆塔尔");
    Add("Survivors from Lordaeron's fall are once more pouring into Andorhal. Eagles and Gryphons from Aerie Peak soar down to the renewed agricultural center to enjoy its renewed production.", "洛丹伦陷落后的幸存者再次涌入安多哈尔。鹰巢山的雄鹰与狮鹫也俯冲而下，来到这座复苏的农业中心，享用重新丰盈的物产。");
    Add("Sylvanas", "希尔瓦娜斯");
    Add("Syrith the Venomous", "剧毒者赛瑞斯");
    Add("Sythrak the Poisoned", "毒浸者赛斯拉克");
    Add("TEAM VICTORY IMMINENT", "队伍胜利在望");
    Add("TEAM VICTORY!", "队伍胜利！");
    Add("Tales of Cairne's strength and wisdom reverberate throughout Kalimdor. As strength is drawn to strength, the Ragetotem are drawn to the Bloodhoof.", "凯恩的力量与智慧的故事传遍了整个卡利姆多。正如力量彼此吸引，狂暴图腾部族也归附了血蹄部族。");
    Add("Taming the Maelstrom", "驯服大漩涡");
    Add("Tanin Hawkwing", "塔宁·鹰翼");
    Add("Tank", "坦克");
    Add("Tauren Tribes", "牛头人部族");
    Add("Tech-Orb 4000", "科技宝珠 4000");
    Add("Teleport", "传送");
    Add("Teleport activated. Use patrol to move instantly.", "传送已激活。使用巡逻命令即可瞬间移动。");
    Add("Teleport deactivated. Patrol works normally.", "传送已关闭。巡逻恢复正常。");
    Add("Tempest Keep still has the power to open a portal Argus, but Velen needs to channel it", "风暴要塞仍有开启通往阿古斯传送门的力量，但需要维伦来引导它");
    Add("Tempesthorn", "风暴之角");
    Add("Temple of Ahn'Qiraj", "安其拉神殿");
    Add("Tenn Flamecaster", "特恩·炎法师");
    Add("Tenris Mirkblood", "特里斯·黯血");
    Add("Teron Gorefiend can be trained at the altar and learn to train {count} {unit}s from the {building}", "塔隆·血魔可在祭坛中训练，并可学会从{building}训练{count}个{unit}");
    Add("Terrak Emberforge", "泰拉克·余烬熔炉");
    Add("Terrordar", "泰罗达尔");
    Add("Tess Greymane calls to Goldrinn's spirit. Revolted at the horrors that his fang had wrought on the Gilnean people but impressed with their ferocity, he returns to the mortal world, ready to rend and tear for his new people.", "苔丝·格雷迈恩呼唤戈德林之灵。他虽对自己之牙给吉尔尼斯人带来的恐怖感到厌恶，却也折服于他们的凶悍，于是重返凡间，准备为他的新子民撕咬厮杀。");
    Add("Thaddeus Blackpowder", "塔迪乌斯·黑火药");
    Add("Thalassa Darkwave", "萨拉萨·暗涛");
    Add("Thalindra Moonshade", "萨琳德拉·月影");
    Add("Thalindra Waveguard", "萨琳德拉·浪潮卫士");
    Add("Thalir Firebane", "萨利尔·焚祸");
    Add("Thalnoth the Fang", "利牙者萨尔诺斯");
    Add("Thalorin Lightstrike", "萨洛林·圣光之击");
    Add("Thalrix the Impaler", "穿刺者萨尔里克斯");
    Add("Thane Valemort Creed", "瓦勒莫特·克里德领主");
    Add("Tharok Silverclaw", "萨洛克·银爪");
    Add("That has to be where Mal'Ganis is hiding! I want that base leveled!", "那里一定是玛尔加尼斯的藏身之所！给我夷平他的基地！");
    Add("That is not a valid object ID for this map.", "这不是本地图中有效的对象编号。");
    Add("The Abyss", "深渊");
    Add("The Amani Trolls have been harassing Silvermoon since its founding, but their defensive position within their jungle has made the prospect of an all-out assault too costly. Today, however, the Amani begins their largest siege yet. They leave us no choice; we must scour Zul'aman if the High Elves are to prosper.", "自银月城建立以来，阿曼尼巨魔便不断侵扰，但他们盘踞丛林、防御稳固，令全面进攻的代价过于高昂。然而今日，阿曼尼发动了迄今为止规模最大的围攻。他们让我们别无选择；高等精灵若要繁荣昌盛，就必须将祖阿曼彻底荡平。");
    Add("The Amani trolls have been eliminated, settling a racial feud that had persisted for millenia.", "阿曼尼巨魔已被消灭，延续千年的种族宿怨就此了结。");
    Add("The Aqir have joined my ranks in glory again!", "亚基虫人再度荣耀地加入了我的行列！");
    Add("The Artifact", "神器");
    Add("The Barrow Den", "兽穴");
    Add("The Black Empire has poured out near Feathermoon and begun threatening the wilds. These invaders must be repelled.", "黑暗帝国的大军已涌至羽月要塞附近，开始威胁这片荒野。必须击退这些入侵者。");
    Add("The Black Temple in Shadowmoon Valley is the capital for the forces of Outland. We must destroy it to stop the external threat once and for all.", "影月谷的黑暗神殿是外域势力的都城。我们必须摧毁它，才能一劳永逸地终结这场外来威胁。");
    Add("The Blackrock clan has taken over Alterac, they must be eliminated for the safety of Lordaeron", "黑石氏族已占据了奥特兰克，为了洛丹伦的安全，必须将他们消灭");
    Add("The Blade of the Black Empire appears near The Abyss", "黑暗帝国之刃出现在深渊附近");
    Add("The Blue Dragons of Northrend are the wardens of magic on Azeroth. They might be convinced to willingly join the mages of Dalaran.", "诺森德的蓝龙是艾泽拉斯魔法的守护者。或许能说服他们自愿加入达拉然的法师阵营。");
    Add("The Book of Medivh", "麦迪文之书");
    Add("The Book of Medivh, which can be used to summon the full might of the Burning Legion", "麦迪文之书，可用以召唤燃烧军团全部的力量");
    Add("The Broken Isles have been scoured, and it is now clear that the way to the Tomb of Sargeras is closed. Illidan must return to Outland, biding his time before he is strong enough to unlock the Tomb's secrets.", "破碎群岛已被彻底搜查，如今真相大白：通往萨格拉斯之墓的道路已经封闭。伊利丹必须返回外域，静待时机，直到自己强大到足以揭开陵墓的秘密。");
    Add("The Burning Legion is being summoned!", "燃烧军团正在被召唤！");
    Add("The Crimson Cathedral has been destroyed", "血色大教堂已被摧毁");
    Add("The Crimson Cathedral has been established in Northrend. Seeing first-hand that the Light can reach even the darkest places of the world, what few shreds of doubt lingering in Brigitte Abbendis' soul evaporate.", "血色大教堂已在诺森德落成。亲眼见证圣光连世间最黑暗之处也能照及，布丽奇特·阿比迪斯灵魂中残存的些许疑虑也随之烟消云散。");
    Add("The Crusade finally manages to establish a foothold in Northrend. Already the land's dark influence pierces the mind of even its most stalwart Archons.", "十字军终于在诺森德站稳了脚跟。这片土地的黑暗影响，已然侵入它最坚定的执政官们的心智。");
    Add("The Crusade's architects have drawn up plans for an ornate cathedral, to be erected in the frozen wastes of Northrend. It shall be a beacon in the dark.", "十字军的建筑师们已绘制出一座华丽大教堂的图纸，将在诺森德的冰封荒原上动工兴建。它将成为黑暗中的一座灯塔。");
    Add("The Cult of the Damned is prepared to unleash a devastating zombifying plague across the lands of Lordaeron.", "诅咒教派已准备好向洛丹伦全境释放一场毁灭性的僵尸瘟疫。");
    Add("The Dark Lord said you would come. This is where your journey ends, boy. Trapped and freezing at the roof of the world, with only death to sing the tale of your doom.", "黑暗之主料到你会来的，小子。你的旅程将在此终结，在这冰封的世界屋脊，深陷绝境、无处可逃，唯有死亡将你陨灭的故事传诵。");
    Add("The Dark Portal can be used to teleport units between the Eastern Kingdoms and Outland", "黑暗之门可用于在东部王国与外域之间传送单位");
    Add("The Dark Portal closes permanently and Khadgar gains", "黑暗之门永久关闭，卡德加获得");
    Add("The Dark Portal closes permanently and Khadgar gains 10000 experience", "黑暗之门永久关闭，卡德加获得 10000 点经验值");
    Add("The Dark Portal has been a menace to the Kingdom of Stormwind for decades, it is time to end the menace once and for all.", "数十年来，黑暗之门一直是暴风王国的心腹大患。是时候彻底终结这一威胁了。");
    Add("The Dark Portal, previously thought to have been sealed forever, has been opened once more. The people of Stormwind are about to relive their worst nightmares, as the demonic Fel Horde spills forth from Outland to resume their slaughterous rampage.", "本以为已被永久封印的黑暗之门再度开启。暴风城的人民即将重温他们最深的噩梦——恶魔般的邪部落自外域涌出，重启他们的血腥暴行。");
    Add("The Darkspear Trolls have been brought to heel.", "暗矛巨魔已被驯服。");
    Add("The Darkspear Trolls, fierce and cunning warriors, dwell in Echo Isles. It is time we forced their hand.", "暗矛巨魔是凶猛而狡诈的战士，他们居住在回音群岛。是时候逼他们表态了。");
    Add("The Dimensional Generator gains the ability to channel portals to Argus and Outland. The Lightforged units and A'dal will become available", "维度发生器获得开启通往阿古斯与外域传送门的能力。光铸单位与阿达尔将可供使用");
    Add("The Doomhammer", "毁灭之锤");
    Add("The Draenei will need to rebuild their civilisation in Azeroth. Darkshore seems like a perfect place for the birth of the second Draenei settlement.", "德莱尼人需要在艾泽拉斯重建他们的文明。黑海岸似乎是建立第二座德莱尼定居点的绝佳地点。");
    Add("The Dreadlords drink freely of the Sunwell. The energies that once coursed through the waters of the well now course through the veins of the Nazrethim, infusing them with power enough to tear holes in dimensions.", "恐惧魔王们尽情畅饮太阳之井的井水。曾在这口井的水中奔涌的能量，如今流淌在纳斯雷兹姆的血脉之中，赋予他们足以撕裂维度的力量。");
    Add("The Dreadlords have played a subtle hand in preparing Lordaeron for the coming of the Scourge. Once the Plague is unleashed, the Dreadlords will activate their own assets.", "恐惧魔王们一直在暗中布局，为天灾的降临铺平洛丹伦的道路。一旦瘟疫被释放，恐惧魔王便会启用他们自己的棋子。");
    Add("The Dwarven Dominion must be established before Ironforge can join the war.", "必须在铁炉堡参战之前建立起矮人霸权。");
    Add("The Elves of Quel'thalas have a deep reliance on the Sunwell's magic. But perhaps in these dark times, they might turn to darker magicks to sate themselves.", "奎尔萨拉斯的精灵极度依赖太阳之井的魔法。但或许在这黑暗的时代，他们可以转向更黑暗的魔法来满足自己。");
    Add("The Exodar Generator becomes invulnerable until all Crystal Protectors around it have been destroyed", "在所有环绕它的水晶守护者被摧毁之前，埃索达发生器处于无敌状态");
    Add("The Exodar is destroyed. It can never be repaired again.", "埃索达已被摧毁。它再也无法修复了。");
    Add("The Exodar's core has been rebuilt - the Crystal Protectors around it now shield it from any harm.", "埃索达的核心已经重建——环绕它的水晶守护者如今会为它抵挡一切伤害。");
    Add("The Explorer's League has been established in Ironforge, and they have set out on their first expedition.", "探险者协会已在铁炉堡成立，并已踏上他们的首次远征。");
    Add("The Explorer's League have identified areas of interest in the foreign lands of Kalimdor. We should set forth on another expedition to uncover their secrets.", "探险者协会已在卡利姆多这片异域之地发现了多处值得探查的区域。我们应当再次启程远征，揭开那里的秘密。");
    Add("The Fountain of Blood is under Warsong control. As the orcs drink from it, they feel a a familiar fury awake within them.", "鲜血之泉已处于战歌氏族的掌控之下。当兽人饮下泉水时，他们感到一股熟悉的狂怒在体内苏醒。");
    Add("The Frozen Throne has been ruptured beyond repair, but Ner'zhul's mangled soul remains imprisoned within. Perhaps the old Shaman will never know peace.", "冰封王座已被撕裂得无法修复，但耐奥祖残破的灵魂仍被囚禁其中。也许这位老萨满永远无法得到安宁。");
    Add("The Frozen Throne is {state}", "冰封王座{state}");
    Add("The Frozen Throne, once thought to be an indomitable bastion of death, has been ruptured. Ner'zhul's consciousness recedes within, retreating desperately to protect what remains of Icecrown Citadel.", "曾被视作不可撼动的死亡堡垒的冰封王座已经破裂。耐奥祖的意识向内退却，拼命收缩，以守护冰冠堡垒残存的部分。");
    Add("The Gilneans, fearful of a potential invasion from the frozen north, sealed themselves behind the Greymane Wall. If we are to survive the coming storm, we must force our neighbor back out into the open.", "吉尔尼斯人因惧怕来自冰封北方的入侵，将自己封锁在格雷迈恩之墙之后。若要在这场即将到来的风暴中幸存，我们必须迫使这位邻邦重新走出高墙。");
    Add("The Gnolls have been defeated, Goldshire is safe.", "豺狼人已被击败，闪金镇安全了。");
    Add("The Great Forge", "大熔炉");
    Add("The Great Forge has been annihilated. The Fel Horde's peons immediately salvage its intact refineries and put them to purpose in the creation of Felsteel.", "大熔炉已被夷为平地。邪部落的苦工立即抢救出尚且完好的精炼设备，将其用于魔钢的制造。");
    Add("The Great Forge has been extinguished.", "大熔炉已经熄灭了。");
    Add("The Great Hall falls, but the survivors scramble aboard what's left of the fleet and limp toward Kalimdor regardless.", "大厅陷落了，但幸存者仍挣扎着登上残存的船只，一瘸一拐地驶向卡利姆多。");
    Add("The Great Kingdom of Gilneas has been reduced to its land behind the Greymane Wall, We must reclaim our lost land to regain our strength.", "伟大的吉尔尼斯王国已萎缩至格雷迈恩之墙以内的土地。我们必须夺回失去的领土，才能重获力量。");
    Add("The High Elves of Quel'thalas have in their possession a well of immense arcane energy. A mere vial of it would be of extraordinary value, if only we could get our hands on one.", "奎尔萨拉斯的高等精灵拥有一口蕴含磅礴奥术能量的井。只要弄得到手，哪怕仅仅一小瓶，也价值非凡。");
    Add("The Horde shamans, through rituals, are preventing me from expanding through the earth. I will need to destroy the seats of their power", "部落的萨满祭司正以仪式阻止我通过大地向外扩张。我必须摧毁他们力量的根基。");
    Add("The Horde still needs to establish a strong strategic foothold into Kalimdor. Expand into the Barrens and claim the Crossroads.", "部落仍需在卡利姆多建立稳固的战略据点。向贫瘠之地扩张，并夺取十字路口。");
    Add("The King of Stormwind dies a warrior’s death, defending hearth and family. The Wrynn Dynasty crumbles with his passing.", "暴风城国王以战士之姿战死，为守护家园与亲人而亡。随着他的逝去，乌瑞恩王朝随之崩塌。");
    Add("The Kingdom of Lordaeron has fallen, eliminating Azeroth's vanguard against the Legion.", "洛丹伦王国已经覆灭，艾泽拉斯抵御军团的先锋就此被铲除。");
    Add("The Kingdom of Lordaeron must be eliminated to pave the way for the Legion's arrival.", "必须消灭洛丹伦王国，才能为军团的降临铺平道路。");
    Add("The Kul Tiran outpost in Westfall has been completed. In the mean time, the Ember Order has cleansed House Waycrest of their Drust influence. Meredith Waycrest has been released from her pact, and may now join the war effort.", "库尔提拉斯在西部荒野的前哨已经建成。与此同时，灰烬骑士团已清除了德鲁斯特对维克雷斯家族的操控。梅瑞狄斯·维克雷斯已从契约中解脱，如今可以加入战争了。");
    Add("The Legion Nexus has been obliterated. A group of ambitious mages seize the opportunity to study the demons' magic, becoming the first Blood Mages.", "军团魔枢已被摧毁。一群野心勃勃的法师抓住机会研究恶魔的魔法，成为了第一批血法师。");
    Add("The Legion has returned to consume this world, woman. And this time, your troublesome race will not stop us.", "燃烧军团回来吞噬这个世界了，女人。而这一次，你们一族不会再成为我们的绊脚石了。");
    Add("The Legion will need a hidden stronghold to house a demon gate, the Shadowfang Keep is perfectly out of the way for the role.", "军团需要一处隐蔽的据点来安置恶魔之门，而影牙城堡的位置对此再合适不过。");
    Add("The Lich King has foretold that the human necromancer Kel'thuzad will be slain by the enemies of the Scourge. Fortunately for him, he will live on in an ethereal form.", "巫妖王预言，人类通灵师克尔苏加德将被天灾的敌人杀死。幸运的是，他将以幽灵形态继续存在。");
    Add("The Lord of the Forest, Cenarius, has fallen. The druids of the Kaldorei have lost their greatest mentor.", "森林之王塞纳留斯已经陨落。卡多雷的德鲁伊们失去了他们最伟大的导师。");
    Add("The Maelstrom still hides the shattered Well of Eternity. With his immense power, Kil'jaeden can summon a new well that will bring forth the destruction of the world.", "大漩涡之下仍掩埋着破碎的永恒之井。凭其无上力量，基尔加丹可召唤出一口新的井，为这个世界带来毁灭。");
    Add("The Monastery has been corrupted and plundered. A secret demon gate has now been formed inside.", "修道院已被腐化并遭洗劫。一道秘密的恶魔之门如今已在其中成形。");
    Add("The Naga explorers in the Cape of Stranglethorn are rejoined with the Illidari forces from Outland, and are eager to battle the Alliance.", "荆棘谷海角的纳迦探子重新与来自外域的伊利达雷部队会合，他们渴望与联盟一战。");
    Add("The Necromancer Kel'thuzad has been immersed in the Sunwell and reborn as a Lich. The well, formerly a beacon of eternal light and power, has been twisted into a font of dark magic, spreading malevolence across the land.", "通灵师克尔苏加德已浸入太阳之井，重生为巫妖。这口井曾是永恒光明与力量的化身，如今已被扭曲为黑暗魔法的源泉，将邪恶散播到整片土地。");
    Add("The Nexus has been captured. The Blue Dragonflight fights for Dalaran.", "魔枢已被占领。蓝龙军团为达拉然而战。");
    Add("The Old God C'thun has excised from the world, ridding the Legion - and Azeroth - of an ancient threat. The Deceiver upholds his end of the bargain, and bestows unto the Illidari his gift.", "上古之神克苏恩已被逐出这个世界，为军团——也为艾泽拉斯——除去了一桩古老的威胁。欺诈者履行了他的承诺，将他的馈赠赐予伊利达雷。");
    Add("The Old Gods C'Thun and N'Zoth threaten to spread chaos across the land. By eliminating these ancient terrors, the Warsong may claim victory and infuse their warriors with newfound strength.", "上古之神克苏恩与恩佐斯威胁要将混乱散播到整个大地。消灭这些远古的恐怖存在，战歌氏族便能赢得胜利，并为其战士注入全新的力量。");
    Add("The Orc Warlock Gul'dan is ultimately responsible for the formation of the Fel Horde. Though long dead, his teachings could still be extracted from his body.", "兽人术士古尔丹正是邪部落得以建立的罪魁祸首。尽管他早已死去，但我们仍可从他的遗骸中攫取他的教诲。");
    Add("The Orc threat from Draenor still looms over all. Eliminate every trace of the Orcs and their bases.", "来自德拉诺的兽人威胁依旧笼罩着一切。消灭兽人的每一处踪迹及其基地。");
    Add("The Qiraji have bursted out of their underground city. They need to be ridden from the surface of Kalimdor.", "其拉虫人已从他们的地下城市中涌出。必须将他们从卡利姆多的地表上清除。");
    Add("The Qiraji presence on Kalimdor has been eliminated. The sacred lands are safe from them.", "其拉虫人在卡利姆多的势力已被肃清。这片圣地不再受其威胁。");
    Add("The Ragetotem Tribe are renowned for their martial prowess. An older, mightier Cairne might convince them to join the Bloodhoof.", "狂暴图腾部族以其武艺而闻名。一位更年长、更强壮的凯恩或许能说服他们加入血蹄部族。");
    Add("The Scarab Gong", "甲虫之锣");
    Add("The Scarlet Crusade has successfully rebuilt Lordaeron City, cementing their position as the rightful successors of Lordaeron's legacy.", "血色十字军成功重建了洛丹伦城，巩固了其作为洛丹伦正统继承者的地位。");
    Add("The Sentinels have rebuilt Feathermoon Stronghold to its former glory. Maiev Shadowsong now joins their efforts.", "哨兵们已将羽月要塞重建，恢复了昔日的荣光。玛维·影歌如今也加入了他们的行列。");
    Add("The Shen'dralar, the Highborne survivors of the Sundering, swear allegiance to their fellow Night Elves. As a sign of their loyalty, they offer up an artifact they have guarded for thousands of years: the Scepter of the Queen.", "辛德拉——大分裂后幸存的上层精灵——宣誓效忠自己的暗夜精灵同胞。为表忠诚，他们献上了守护数千年的神器：女王权杖。");
    Add("The Soulflayer's blade, though shattered and spread to the corners of Azeroth, still hold immense power. Even Illidan cannot decipher the sword's origin - but he can relish its power.", "夺灵者之刃虽已碎裂、散落于艾泽拉斯各处，却仍蕴含着无穷的力量。即便是伊利丹也无法参透这把剑的来历——但他可以尽情享受它的力量。");
    Add("The Spire has been pillaged. A secret demon gate has now been formed inside.", "风行者之塔已遭洗劫。一道秘密的恶魔之门如今已在其中成形。");
    Add("The Strahnbrad is under attack by some brigands, clear them out", "斯坦恩布莱德正遭到一群强盗的袭击，把他们清除掉");
    Add("The Stranglethorn vale is still infested with trolls and pirates. If peace is to be brought back to the South Alliance, it needs to be purged", "荆棘谷依旧遍布巨魔与海盗。若要让南方联盟重归和平，就必须肃清此地");
    Add("The Sunfury have a long, proud history, tracing all the way back to their status as the Highborne. We have forgotten more knowledge than other races have ever known. Perhaps some of it lies within the ruins of the old Highborne kingdom, Suramar.", "日怒有着悠久而自豪的历史，可以一直追溯到他们身为上层精灵的时代。我们遗忘的知识，比其他种族曾知晓的还要多。或许其中一部分，就藏在古老的上层精灵王国苏拉玛的废墟之中。");
    Add("The Sunfury must learn to adapt to their new home within the inhospitable Netherstorm. There are several eco-domes dotted throughout the region, remnants of Netherstorm's prior existence as the verdant Farahlon. They would make excellent locations for growth facilities.", "日怒必须学会适应他们在荒芜虚空风暴中的新家园。这片地区散布着几座生态圆顶，是虚空风暴昔日作为苍翠法兰伦的遗存。它们将是绝佳的种植设施选址。");
    Add("The Sunwell is the source of the High Elves' immortality and magical prowess, created from a stolen vial from the Well of Eternity. The immense power within its waters would be an immense boon to the Legion.", "太阳之井是高等精灵永生与魔法力量的源泉，由自永恒之井窃取的一瓶井水造就。其井水之中蕴含的浩瀚能量，对军团而言将是莫大的助力。");
    Add("The Sunwell, once a source of great magical energy, is no more. Its corruption has ended, and the land is free from its dark influence.", "曾是强大魔法能量之源的太阳之井已不复存在。它的腐化已然终结，这片土地从此摆脱了黑暗的影响。");
    Add("The Tauren have been wandering for too long. The fertile plains of Mulgore would offer respite from this endless journey.", "牛头人已经流浪太久了。莫高雷的肥沃平原将为这无尽的旅程提供一处栖身之所。");
    Add("The Tauren of Thunder Bluff are noble warriors, but their allegiances are uncertain. Bring them into the fold or pillage their lands.", "雷霆崖的牛头人是高贵的战士，但他们的效忠尚不明朗。将他们纳入麾下，或是劫掠他们的土地。");
    Add("The Tauren tribes must abandon their ancestral camp and march east across the Barrens, escorted by a handful of guards, to build a new home at Thunder Bluff. Centaur raiders infest the plains between here and there.", "牛头人部族必须放弃祖辈的营地，在少数护卫的护送下东行穿越贫瘠之地，去雷霆崖建立新的家园。沿途的平原上遍布半人马劫掠者。");
    Add("The Third War is over. Archimonde has successfully consumed the energies of the Well of Eternity resting beneath Nordrassil. The last line of defense against the Burning Legion has fallen, and with it dies the hopes and dreams of Azeroth.", "第三次大战已然终结。阿克蒙德成功汲取了诺达希尔之下那口永恒之井的能量。抵御燃烧军团的最后一道防线已经崩溃，艾泽拉斯的希望与梦想也随之破灭。");
    Add("The Thunder Eagles of the Storm Peaks live in fear of the Legion. Wipe out the Legion Nexus to bring these great birds out into the open.", "风暴峭壁的雷鹰生活在燃烧军团的阴影之下。摧毁军团魔枢，让这些巨鸟现身于世。");
    Add("The Titan Construct has fallen, and C'thun stirs within his prison. The Old God is free to spread chaos once more.", "泰坦造物已经倒下，克苏恩在他的牢笼中苏醒。上古之神重获自由，可以再度散播混乱了。");
    Add("The Tomb of Sargeras has been opened by {unit}.", "萨格拉斯之墓已被{unit}打开。");
    Add("The Tomb of Sargeras opens", "萨格拉斯之墓开启了");
    Add("The Violet Citadel", "紫罗兰城堡");
    Add("The Violet Citadel, the ultimate bastion of arcane knowledge in the Eastern Kingdoms, crumbles like a sand castle.", "紫罗兰城堡，东部王国奥术知识的终极堡垒，此刻却像一座沙堡般轰然崩塌。");
    Add("The Vortex Pinnacle has been captured by the Horde. Drek'thar has gifted Warchief Thrall his magical spellbook for this achievement.", "旋云之巅已被部落占领。为表彰这一功绩，德雷克塔尔将他的法术书赠予了大酋长萨尔。");
    Add("The Warden Maiev presided over Illidan's imprisonment in the barrow prisons for ten thousand years. His escape has spurred on a relentless quest for vengeance, and nothing short of death will stop her.", "一万年来，守望者玛维一直在兽穴牢狱中看守着被囚禁的伊利丹。他的逃脱激起了她无休无止的复仇之旅，不取其性命，她绝不罢休。");
    Add("The Warden Shadowsong has been gravely wounded, stopping her pursuit of Illidan - for now.", "守望者影歌身负重伤，被迫中止了对伊利丹的追捕——至少暂时如此。");
    Add("The Warsong Clan has set sail for the icy shores of Northrend and set up a formidable encampment at Borean Tundra.", "战歌氏族已扬帆驶向诺森德的冰封海岸，并在北风苔原建立起一座坚固的营地。");
    Add("The Warsong has drunk the blood of Mannoroth. It will take Thrall 4 minutes to save Grom and purify the Warsong Clan orcs.", "战歌氏族已饮下玛诺洛斯之血。萨尔需要 4 分钟才能救回格罗姆，并净化战歌氏族的兽人。");
    Add("The Warsong is still vulnerable to the tentation of Mannoroth's Blood. If they drink it from the Fountain, they would have a surge of power. Although, Thrall would certainly hurry to save his friend Grom from the corruption.", "战歌氏族仍然无法抵御玛诺洛斯之血的诱惑。若他们饮下鲜血之泉的泉水，力量便会急剧膨胀。不过，萨尔必定会赶去将好友格罗姆从腐化中拯救出来。");
    Add("The Wildhammer dwarves roam freely over the peaks of the Hinterlands. An audience with them might earn their cooperation.", "蛮锤矮人自由自在地游荡在辛特兰的群峰之间。前去拜会他们，或许能赢得他们的合作。");
    Add("The Windrunner tower is a strong asset to Quel'thalas.", "风行者之塔是奎尔萨拉斯的强大助力。");
    Add("The Worgen curse originated from Goldrinn, the embodiment of ferocity, savagery, and unyielding will. Traveling to Mount Hyjal we might contact the wolf god to help us against our curse.", "狼人诅咒源自戈德林——凶暴、野性与不屈意志的化身。前往海加尔山，我们或许能联系上这位狼神，助我们对抗自身的诅咒。");
    Add("The World Tree", "世界之树");
    Add("The World Tree Shaladrassil was planted in the land once known as Val'sharah, the cradle of Druidic culture. Val'sharah was shattered by the Great Sundering along with the rest of the Broken Isles. The tree still remains, but without a Druidic presence it will wither in time.", "世界之树莎拉达希尔曾栽种在如今被称为瓦尔莎拉的土地上，那里是德鲁伊文化的摇篮。瓦尔莎拉在大分裂中随破碎群岛的其余部分一同崩碎。这棵树至今犹存，但若没有德鲁伊的照料，它终将枯萎。");
    Add("The World of Azeroth is mine.", "艾泽拉斯世界归我所有。");
    Add("The abominable sandwurm Ouro has been created by Cthun", "可憎的沙虫奥罗已由克苏恩创造而出");
    Add("The ancient Vault of the Wardens has been secured. Maiev and her Wardens take up residence within its ancient halls.", "古老的守望者地窟已被夺取。玛维与她的守望者们在它古老的殿堂中安顿下来。");
    Add("The axe of Grom Hellscream has sown terror across hundreds of battlefields.", "格罗姆·地狱咆哮的战斧曾让数百个战场为之胆寒。");
    Add("The blighted tumour of the Sunwell has been excised from the Thalassian homeland. Its people have already turned their magical thirst elsewhere, drawing upon the magicks of {font}.", "太阳之井的枯萎毒瘤已从萨拉斯人的家园中剜除。那里的人民已将魔法的渴求转向他处，转而汲取{font}的魔力。");
    Add("The broken core of the Exodar should be rebuilt, bringing us one step closer to making it usable again.", "埃索达破损的核心应当重建，这将让我们离使它重新可用更近一步。");
    Add("The caravan reaches {rect}", "商队抵达 {rect}");
    Add("The city of Orgrimmar was finally constructed by the Frostwolf engineers, it is now a home for the new Horde and a symbol of power and innovation. Rexxar has now joined the Horde!", "奥格瑞玛城终于由霜狼氏族的工程师建成，如今它是新部落的家园，也是力量与革新的象征。雷克萨现已加入部落！");
    Add("The city of Orgrimmar was finally constructed by the Horde's own engineers, it is now a home for the Horde and a symbol of power and innovation.", "奥格瑞玛城终于由部落自己的工程师建成，如今它既是部落的家园，也是力量与创新的象征。");
    Add("The city of Orgrimmar was finally constructed by the Warsong engineers, it is now a home for the new Horde and a symbol of power and innovation. The Warchief has rewarded us generously for our work!", "奥格瑞玛城终于由战歌氏族的工程师建造完成，如今它是新部落的家园，也是力量与革新的象征。大酋长已为我们的功绩给予了丰厚的奖赏！");
    Add("The city of Stratholme once more stands as a bastion of human civilization. Though still a mere shadow of its former glory, it will reclaim its majesty in time.", "斯坦索姆再次成为人类文明的堡垒。尽管它如今仍只是昔日荣光的一道残影，但终有一日，它会重拾威严。");
    Add("The city of Tyr's Hand is considered impregnable, but they will be reluctant to join the war.", "世人坚信提尔之手坚不可摧，但他们不愿卷入战争。");
    Add("The city-fortress of Tyr's Hand has decided to join us! Renowed for their siege engineers, we can now build siege workshops.", "要塞之城提尔之手已决定加入我们！他们以攻城技师闻名，我们现在可以建造攻城车间了。");
    Add("The clans holding Hellfire Citadel do not respect Kargath's authority yet, Magtheridon is being kept alive by Illidan, if we break him, he could serve us well.", "占据地狱火堡垒的众氏族尚未承认卡加斯的权威。伊利丹留了玛瑟里顿一命；若能击垮他的意志，他定能为我们所用。");
    Add("The core of the Exodar is rebuilt, but it requires a great source of power to function again. Finding that source of power would make the Exodar a powerful asset for the Draenei.", "埃索达的核心已经重建，但要再度运转，它还需要一个强大的能量源。找到那个能量源，将使埃索达成为德莱尼人的强力依仗。");
    Add("The day he was born, the very forests of Lordaeron whispered the name Arthas - but no King rules forever.", "他降生的那一天，洛丹伦的森林都在低语着阿尔萨斯的名字——但王权没有永恒。");
    Add("The desolated village of Brill was once the hometown of Renault Mograine. Though insignificant in the grand scheme of things, the Crusade cares for its members.", "荒废的布瑞尔村曾是雷诺·莫格莱尼的故乡。尽管在宏图大业中无足轻重，但十字军关心它的成员。");
    Add("The destruction of the original Well of Eternity tore apart the Azerothean supercontinent. The rupturing of its second successor reaches no such heights, but its absence is felt by Elves and arcanists the world over.", "最初永恒之井的毁灭撕裂了艾泽拉斯超大陆。其第二代继承者的崩裂虽远不及此，但全世界的精灵与奥术师都能感受到它的缺失。");
    Add("The distant lands of Kalimdor remain untouched by human civilization. If the Third War proceeds poorly, it may become necessary to abandon Dalaran and establish a refuge there.", "遥远的卡利姆多尚未被人类文明触及。倘若第三次大战进展不利，也许有必要放弃达拉然，在那里建立一处避难所。");
    Add("The elemental plane has launched a massive invasion at the world tree.", "元素位面已对世界之树发动大规模入侵。");
    Add("The elemental planes are out of control. Bring Thrall to the Vortex Pinnacle to bring back the balance.", "元素位面已经失控。将萨尔带到旋云之巅，恢复平衡。");
    Add("The elements of Azeroth are in terrible disarray, and the situation only grows worse as rising conflicts threaten to tear our world apart. Thrall, as one of the most formidable Shamans of his time, must take up the mantle of the World-Shaman if he is to save his people - and the world.", "艾泽拉斯的元素陷入了可怕的混乱，而随着愈演愈烈的冲突威胁要将我们的世界撕裂，局势只会日益恶化。作为他那个时代最强大的萨满祭司之一，萨尔必须肩负起救世萨满的重任，才能拯救他的人民——以及整个世界。");
    Add("The far-off land of Northrend is the new home of the traitor shaman Ner'zhul. The Warsong must land its forces on its shores in order to end the existential threat he now represents.", "遥远的诺森德是叛徒萨满耐奥祖的新家园。战歌氏族必须将其部队送上那片海岸，才能终结他所带来的存亡威胁。");
    Add("The fastest way to travel between continents is by using items of type {item}.", "在大陆之间旅行最快的方式是使用{item}类型的物品。");
    Add("The fate of the ogres has been decided, and the Horde's power grows.", "食人魔的命运已然注定，部落的力量日益壮大。");
    Add("The fel orcs have been vanquished from Blackrock Spire and {hero} has convinced Dagran and his Dark Iron dwarves to join our cause.", "邪兽人已被逐出黑石塔，{hero}说服了达格兰和他的黑铁矮人加入我们的事业。");
    Add("The fleet departs for Durotar, taking all surviving forces with it", "舰队启航前往杜隆塔尔，带走所有幸存的部队");
    Add("The forest needs healing. Regain control of it to awaken it.", "森林需要治愈。夺回它的控制权，便能将其唤醒。");
    Add("The fortress of the Stonemaul Clan has fallen.", "石槌氏族的堡垒已被攻陷。");
    Add("The frail elves do not concern me, necromancer. Our forces are strengthened with every foe we slay.", "这些精灵不值一提，通灵师。每干掉一个敌人，都会让我们的部队变得更强。");
    Add("The glorious kingdom of Ahn'Qiraj has now been rebuilt. The gates are open, and the world shall fear the Qiraji once more.", "辉煌的安其拉王国如今已经重建。大门已经敞开，世界将再次畏惧其拉虫人。");
    Add("The goblins of Area 52 have lived in Netherstorm long before our arrival. In other circumstances, they may have been potential allies - but desperate times call for desperate conquests.", "早在我们到来之前，52 区的地精就已经居住在虚空风暴了。换作别的情形，他们或许会是潜在的盟友——但非常之时，需行非常之征服。");
    Add("The goblins of Area 52 once aspired to travel amongst the stars. Now they aspire to nothing, buried one layer of dirt beneath our new settlement.", "52 区的地精曾渴望遨游星海。如今他们再无所求，只余一抔黄土，长眠于我们新定居点之下。");
    Add("The grand city of the high elves, Silvermoon, has been crushed by her enemies.", "高等精灵的宏伟之城银月城已被她的敌人摧毁。");
    Add("The great Stronghold of the Legian has fallen", "军团的大据点已经陷落");
    Add("The greater forces of the Burning Legion lie in wait in the vast expanse of the Twisting Nether. Use the Book of Medivh to tear open a hole in space-time, and visit the full might of the Legion upon Azeroth.", "燃烧军团更庞大的军势正蛰伏于扭曲虚空的广袤深处。用麦迪文之书撕开一道时空裂口，让军团的全副威势降临艾泽拉斯。");
    Add("The hero Archimonde, control of all units in the Twisting Nether. Anetheron improves his Vampiric Siphon ability", "英雄阿克蒙德，扭曲虚空全境单位的控制权。安纳塞隆强化他的吸血虹吸技能");
    Add("The hero Rohkan is now trainable at the Altar", "现在可以在祭坛中训练英雄洛坎");
    Add("The hive needs to grow and spread to thrive. The sands of Silithus are perfect for that purpose, but the surroundings will have to be secured first.", "虫巢需要生长蔓延才能繁荣。希利苏斯的沙海正适合这一目的，但必须先确保周边地区的安全。");
    Add("The horn has sounded, and I have come as promised! I smell the stench of decay and corruption in our land. That angers me greatly.", "号角振声而起，而我如约归来！我闻到我们的土地上飘荡着腐败凋零的恶臭。我，很愤怒。");
    Add("The invasion of the World Tree has been unleashed! The forces of Kalimdor have to protect it at all cost.", "对世界之树的入侵已然发动！卡利姆多的军队必须不惜一切代价保卫它。");
    Add("The kodo caravan is lost along the way, but the Tauren tribes stagger into Thunder Bluff regardless, battered and few.", "科多兽商队在半途失散，但牛头人部族仍踉跄着抵达了雷霆崖——伤痕累累，所剩无几。");
    Add("The land has been secured. I can now expand the hive warrens to Silithus.", "这片土地已被拿下。现在我可以将虫巢巢穴扩张到希利苏斯了。");
    Add("The last of the murlocs sink beneath the waves. With the coast clear, the fleet sets sail for Kalimdor.", "最后一批鱼人沉入波涛之下。海岸既已肃清，舰队便启航前往卡利姆多。");
    Add("The last remaining spellbook written by Medivh, the Last Guardian, is held securely within {location}. The spells within its pages could bring us great power.", "最后一任守护者麦迪文所著、世间仅存的法术书，被严密保管在{location}。书页中的法术能为我们带来强大的力量。");
    Add("The living crystal of the Crystalsong Forest suffers from its proximity to the Legion. Freed from that corruption, it could be used to empower Dalaran's constructs.", "晶歌森林的活体水晶因邻近燃烧军团而饱受侵蚀。若能摆脱那份腐化，它便可用来强化达拉然的构造体。");
    Add("The long march of the Tauren clans has ended, and they have joined forces with the Horde.", "牛头人各部族远征已经结束，他们与部落结成了同盟。");
    Add("The mages of Dalaran has decided to submit to our might after noticing our resurgent control of Southern-Lordaeron to help defeat the Scourge.", "达拉然的法师们注意到我们已重新掌控洛丹伦南部，于是决定屈服于我们的力量，协助击败天灾。");
    Add("The majestic city of Stratholme has been destroyed.", "宏伟的斯坦索姆城已被摧毁。");
    Add("The mesas of Thunderbluff have been swept clean of the Tauren. The Bloodhoof are without a home.", "雷霆崖的台地已被牛头人清扫一空。血蹄部族失去了家园。");
    Add("The mighty ancestral sword of the Trollbane.", "托尔贝恩家族强大无比的祖传之剑。");
    Add("The mind of humans are feeble and easily corruptable, the Scarlet Monastery will be a perfect ground for a secret demon portal", "人类的心智脆弱，极易被腐化，血色修道院将是建造一座秘密恶魔传送门的绝佳地点");
    Add("The missing vial of Eternity, it seems, was used to create yet another Well of arcane energy that has since become the center of High Elven civilization.", "那瓶失踪的永恒井水，似乎被用来创造了另一座奥术能量之井，如今它已成为高等精灵文明的中心。");
    Add("The monstrous Old God N'Zoth threatens Kalimdor with madness and ruin. End his terrifying reign to secure the continent and further the Horde's ambitions.", "可怖的上古之神恩佐斯以癫狂与毁灭威胁着卡利姆多。终结他恐怖的统治，以确保这片大陆的安宁，并推进部落的野心。");
    Add("The naga are yours to command, Lord Illidan. Where you go, we follow.", "纳迦听您差遣，伊利丹大人。无论您去哪里，我们都会跟随。");
    Add("The native Draenei of Outland, led by Elder Sage Akama, aided Illidan in his assault on the Black Temple, but abandoned him when he let Magtheridon live. With invaders on Outland's doorstep, the Draenei must be forced back into the fold.", "外域的本土德莱尼由大贤者阿卡玛率领，曾在伊利丹进攻黑暗神殿时相助，但当他饶过玛瑟里顿一命后，他们便弃他而去。如今入侵者已兵临外域门前，必须迫使德莱尼重归麾下。");
    Add("The necrotic taint at the heart of the Sunwell now permeates not only our people, but all we have built. The sacrifice we must make is grave but inevitable: the Sunwell must be destroyed by Thalassian hands.", "太阳之井核心的亡者污秽如今不仅浸染着我们的人民，也浸染着我们的一切造物。我们必须做出的牺牲沉重却无可避免：太阳之井必须由萨拉斯人亲手摧毁。");
    Add("The nightmarish grasp of N'Zoth and the Black Empire has been shattered, allowing Garrosh and the Warsong clan to rally and press forward towards new territories.", "恩佐斯与黑暗帝国的梦魇魔爪已被粉碎，加尔鲁什与战歌氏族得以重整旗鼓，向新的领土进军。");
    Add("The once great kingdom of Ahn'Qiraj was lost to the sands of time. The hive needs to awaken and be rebuilt.", "曾经伟大的安其拉王国已被时间的流沙所吞没。虫巢需要苏醒并重建。");
    Add("The onslaught of the Scourge devastated Lordaeron beyond recognition, slaughtering its people and levelling its cities. Only the Scarlet Crusade stands strong, a faint light of hope in the darkness. If the cities and village of Lordaeron could be reclaimed and rebuilt, humanity could begin again.", "天灾的猛攻将洛丹伦摧残得面目全非，屠戮其人民，夷平其城市。唯有血色十字军屹立不倒，是黑暗中一缕微弱的希望之光。若能夺回并重建洛丹伦的城镇与村庄，人类便能重新开始。");
    Add("The original Aqir, now buried deep beneath the earth, have always served me faithfully. To awaken them once more, I must search in the deepest reaches of Kalimdor: the Stonetalon caverns and the tunnels of Ahn'qiraj.", "最初的亚基虫人如今深埋在泥土之下，他们始终忠心地侍奉着我。要将他们再度唤醒，我必须前往卡利姆多最幽深的所在：石爪山脉的洞窟与安其拉的隧道。");
    Add("The outskirts of Stormwind are infested by rebels and foul creatures. Defeat them to regain control of your lands.", "暴风城郊外遍布叛军与邪恶生物。击败他们，夺回你领地的控制权。");
    Add("The pack kodos survive the march", "驮运科多兽在行军中存活下来");
    Add("The paramater", "参数");
    Add("The people of Gnomeregan have long been unable to assist the Alliance in its wars due an infestation of troggs and Ice Trolls. Resolve their conflicts for them to gain their services.", "由于穴居人与冰巨魔的侵扰，诺莫瑞根的人民长久以来无法在战争中支援联盟。为他们平息纷争，便可赢得他们的效力。");
    Add("The people of the Eastern Kingdoms have been united under the banner of Lordaeron. Long live High King Arthas Menethil!", "东部王国的人民已在洛丹伦的旗帜下团结一心。至高王阿尔萨斯·米奈希尔万岁！");
    Add("The people of the Eastern Kingdoms have been united under the banner of Lordaeron. Long live High King Varian Wrynn!", "东部王国的人民已在洛丹伦的旗帜下团结一心。至高王瓦里安·乌瑞恩万岁！");
    Add("The plague has been unleashed! The citizens of Lordaeron are quickly transforming into mindless zombies", "瘟疫已被释放！洛丹伦的居民正迅速转变为毫无心智的僵尸");
    Add("The plague was never meant to simply kill my people. It was meant to turn them... into the undead! Defend yourselves!", "这场瘟疫从一开始就不是为了夺人性命，而是要把他们……变成亡灵！大家小心！");
    Add("The planet of Argus is not yet fully under the control of the Legion.", "阿古斯星球尚未完全落入军团的掌控。");
    Add("The proud Nerubians have declared war on the newly formed Lich King, destroy them to secure the continent of Northrend.", "骄傲的蛛魔已向新生的巫妖王宣战。消灭他们，以稳固对诺森德大陆的控制。");
    Add("The rangers of Quel'danil have been reunited with the forces of Quel'thalas.", "奎尔丹尼的游侠已与奎尔萨拉斯的部队重新会合。");
    Add("The ravaging hordes of the Qiraji have been consumming Kalimdor. We must put an end to their rampage.", "其拉虫人的大军正在蹂躏卡利姆多。我们必须终结他们的暴行。");
    Add("The ruins all around us, Naisha... I recognize them.", "周围这些残垣断壁，娜萨……我认得他们。");
    Add("The sands of Tanaris call for the Hive, but first I must eliminate the Trolls of Zul'farrak.", "塔纳利斯的沙海在召唤虫巢，但我必须先消灭祖尔法拉克的巨魔。");
    Add("The seat of the Windrunners, pillaging it would yield a great bounty and be the perfect grounds for a demon gate.", "此处是风行者家族的居城，洗劫它既能带来丰厚的战利品，又是建造恶魔之门的绝佳地点。");
    Add("The smiths of Ironforge have long been put to use crafting goods and war machinery. In the hands of the Fel Horde, they could be used to smelt and refine the ultimate metal: Felsteel.", "铁炉堡的铁匠们长久以来一直被驱使打造器物与战争机械。落入邪部落之手后，便可让他们来熔炼并精炼终极金属：魔钢。");
    Add("The spire of Medivh stands mysteriously idle. Dalaran could make use of its grand magicks.", "麦迪文的法师塔神秘静默地矗立着。达拉然或可利用其中宏大的魔法。");
    Add("The temple city of En'kilah is now under the control of the Scourge.", "圣城恩其拉现已被天灾控制。");
    Add("The temple city of En'kilah will be the perfect place for an outpost near the Borean Tundra.", "圣城恩其拉将是北风苔原附近建立前哨的绝佳地点。");
    Add("The territories of Dalaran are fragmented, secure the lands and protect Dalaran citizens.", "达拉然的领土四分五裂，稳固这些土地并保护达拉然的市民。");
    Add("The territories of Lordaeron are fragmented. Regain control of the old Alliance's hold to secure the kingdom.", "洛丹伦的领土四分五裂。夺回旧日联盟据点的控制权，以保王国的安稳。");
    Add("The town of Darkshire is under attack by Gnoll's, clear them out!", "夜色镇正遭受豺狼人的袭击，把他们清除干净！");
    Add("The town of Lakeshire is invaded by Ogres, wipe them out!", "湖畔镇遭到食人魔入侵，把他们彻底消灭！");
    Add("The village of Hearthglen is under siege from the restless dead. The people there must be saved.", "壁炉谷村正遭到不眠亡者的围攻。必须救出那里的民众。");
    Add("The walking corpses assailing Hearthglen have been put back to rest, and Hearthglen lives to see another day.", "袭击壁炉谷的行尸已被重新安息，壁炉谷得以重见明日的曙光。");
    Add("The {mode} game mode has been chosen.", "已选定{mode}游戏模式。");
    Add("The {team} has won the game! You may choose to continue playing.", "{team}已赢得本局游戏！你可以选择继续游戏。");
    Add("Their brute strength is untamed, their loyalty unproven. Subdue the ogres and further strengthen the Horde.", "他们的蛮力桀骜难驯，他们的忠诚尚待证明。驯服这些食人魔，让部落更加强大。");
    Add("There are 4 units of type {unit} scattered throughout the seas, which each give a large amount of income when controlled.", "海域中散布着 4 个{unit}，每控制一个都能带来大量收入。");
    Add("There are water passageways at the edge of the map you can use to instantly move to the other side of the map.", "地图边缘有水上通道，你可以借此瞬间移动到地图的另一侧。");
    Add("There is no Faction with the name {name}.", "没有名为{name}的阵营。");
    Add("There is no Team with the name {name}.", "没有名为{name}的队伍。");
    Add("There is no faction named", "不存在名为以下名称的阵营：");
    Add("There is no player with the Faction {faction}.", "没有玩家使用{faction}阵营。");
    Add("There is nobody playing the", "没有玩家正在扮演");
    Add("Theres a dormant ancient's grove at the base of Hyjal, take control of the area to nurture it back and awaken it!", "海加尔山脚下有一片休眠的远古树林，控制该区域以滋养它并唤醒它！");
    Add("Theta Saberfang", "塞塔·刃牙");
    Add("This is a Light-forsaken land, isn't it? You can barely even see the sun! This howling wind cuts to the bone and you're not even shaking. Mi'lord, are you alright?", "这简直是片被圣光遗弃的土地，天上都看不到太阳！呼啸的寒风冻的人骨头生疼，可您却一抖不抖。殿下，您还好吗？");
    Add("This is a single branch taken from G'Hanir, the first tree.", "这是从第一棵树加尼尔上折下的一根枝条。");
    Add("This is not the Horde you remember, old man. We have no interest in conquest or murder. We have paid for our sins of our forebears in blood.", "我们不是你记忆中的部落，老头子。我们无意攻城略地，也不想残害生灵。先辈种下的恶果已经让我们付出了血的代价。");
    Add("This must be the shrine that the old man spoke of. Any man who drinks from these Light-blessed waters will be healed.", "这一定就是那个老人所说的圣泉了。只要喝下这些圣光祝福的泉水，就能治愈伤病。");
    Add("This new continent is ripe for the taking. If the Horde is to survive, a new city needs to be built.", "这片新大陆正待人夺取。部落若要存续下去，就必须建起一座新的城市。");
    Add("This was once the great city of Suramar, built before our civilization was blasted beneath the sea ten thousand years ago.", "这里曾经是宏伟的苏拉玛城，一万年前的大分裂之后，我们的文明便沉入了海底。");
    Add("Thoradin", "索拉丁");
    Add("Thordin Rockbeard", "索尔丁·石须");
    Add("Thorgas Broadaxe", "索尔戈斯·阔斧");
    Add("Though the town of Hearthglen fell to the Scourge just as easily as any other, the Silver Hand Monastery there makes it a key strategic objective for the Scarlet Crusade.", "尽管壁炉谷与其他城镇一样轻易地陷落于天灾，但那里的白银之手修道院使它成为血色十字军的关键战略目标。");
    Add("Thragor Doomblade", "斯拉戈尔·末日之刃");
    Add("Thrall gains 10 Strength, 10 Dexterity, and 10 Intelligence", "萨尔获得 10 点力量、10 点敏捷和 10 点智力");
    Add("Thrall gains 2000 experience and 15 to all attributes, and you gain the Power Maelstrom Spirit", "萨尔获得 2000 点经验值和 15 点全属性，你获得力量：大漩涡之灵");
    Add("Thrall has stabilized the power of the Maelstrom and stored it within the Doomhammer. He is no longer merely the Warchief of the Horde; he is the World-Shaman of all Azeroth.", "萨尔稳定了大漩涡的力量，并将其封存于毁灭之锤中。他不再仅仅是部落的大酋长；他是整个艾泽拉斯的救世萨满。");
    Add("Thrall's fleet was battered by the crossing and needs time to be made seaworthy again. Until then, the Horde must hold this island against whatever the sea sends at them.", "萨尔的舰队在横渡中受创严重，需要时间才能重新适航。在此之前，部落必须守住这座岛屿，抵挡大海派来的一切敌人。");
    Add("Thrall... I see clearly now.  I'm... sorry.  I am so sorry..", "萨尔……我现在看清了。我……对不起。我真的非常抱歉……");
    Add("Threnos Darkember", "斯雷诺斯·暗烬");
    Add("Thryxis the Shellbreaker", "破壳者斯里克斯");
    Add("Thulgar Bladebreaker", "图尔加·破刃者");
    Add("Thunder elemental from the Pinnacle.", "来自尖塔的雷霆元素。");
    Add("Thunderfury", "雷霆之怒");
    Add("Thundrax", "桑德拉克斯");
    Add("Thurin Stormbreaker", "图林·破风者");
    Add("Thyssara Coralguard", "希萨拉·珊瑚守卫");
    Add("Tichondrius gains 15 Strength, Agility and Intelligence and improves his Vampiric Siphon ability", "提克迪奥斯获得 15 点力量、敏捷与智力，并强化他的吸血虹吸技能");
    Add("To force the mages of Dalaran to submit to our might we must Secure the outlying regions of the Arathi Highlands,", "要让达拉然的法师们屈服于我们的力量，我们必须控制阿拉希高地的外围区域。");
    Add("To force the mages of Dalaran to submit to our might we must Secure the outlying regions of the Arathi Highlands, The Hinterlands and the Troll city of Jintha'alor", "要迫使达拉然的法师屈服于我们的力量，我们必须控制阿拉希高地、辛特兰的外围地区，以及巨魔城市辛萨罗");
    Add("To prepare the destruction of the Lordaeron kingdom, a secret cult will be formed.", "为筹备毁灭洛丹伦王国，一个秘密教派将被建立。");
    Add("Tobias Stormlock", "托拜厄斯·风暴之锁");
    Add("Toggles quest text, dialogue, and captions with a single command (use 'on', 'off', 'true', 'false').", "用一条指令切换任务文本、对话语音与字幕（使用 'on'、'off'、'true'、'false'）。");
    Add("Tojara", "托伽拉");
    Add("Told you my death would mean little.", "我说过，我的死亡无关大局。");
    Add("Tormented spirit of the wind.", "饱受折磨的风之精魂。");
    Add("Tortolla has finally awoken from his ancient slumber.", "托尔托拉终于从远古的沉眠中苏醒。");
    Add("Tortolla was badly wounded during the War of the Ancients, and has been resting ever since.", "托尔托拉在上古之战中身负重伤，此后便一直沉眠至今。");
    Add("Town Hall", "城镇大厅");
    Add("Town Portal Scroll", "回城卷轴");
    Add("Transform your Earth Golems into Crystal Golems", "将你的土元素转化为水晶元素");
    Add("Tree of Life upgrade ability", "生命之树升级");
    Add("Tremble, mortals, and despair! Doom has come to this world!", "颤抖吧，凡人，绝望吧！末日就要降临了！");
    Add("Tricked by Mannoroth into drinking from the corrupted fountain, Grom Hellscream has fallen into demonic fury, locked in battle with the Sentinels. To free him from this enslaving curse, you must defeat Mannoroth the Destroyer himself.", "格罗姆·地狱咆哮受玛诺洛斯诱骗，饮下了被腐化的泉水，陷入恶魔的狂怒之中，与哨兵鏖战不休。要将他从这奴役的诅咒中解放出来，你必须击败毁灭者玛诺洛斯本人。");
    Add("Trol'kalar", "托尔卡拉");
    Add("Troop Production", "作战单位生产");
    Add("Turalyon", "图拉扬");
    Add("Turn {turn} has started", "第 {turn} 回合已经开始");
    Add("Turn {turn} hasn't started", "第 {turn} 回合尚未开始");
    Add("Turns Smart Follow on or off (accepts 'true', 'false', 'on', 'off').", "开启或关闭智能跟随（接受 'true'、'false'、'on'、'off'）。");
    Add("Turns dialogue captions on or off (accepts 'true', 'false', 'on', 'off').", "开启或关闭对话字幕（接受 'true'、'false'、'on'、'off'）。");
    Add("Turns dialogue sound on or off (accepts 'true', 'false', 'on', 'off').", "开启或关闭对话语音（接受 'true'、'false'、'on'、'off'）。");
    Add("Turns quest text on or off (accepts 'true', 'false', 'on', 'off').", "开启或关闭任务文本（接受 'true'、'false'、'on'、'off'）。");
    Add("Twisted Creature from Ny'alotha.", "来自尼奥罗萨的扭曲生物。");
    Add("Tygra Snowscar", "提格拉·雪痕");
    Add("Tyoril Sunchaser", "提奥里尔·猎日者");
    Add("Tyr's Hand, the bastion of human power in Lordaeron, has fallen.", "提尔之手，人类势力在洛丹伦的堡垒，已经陷落。");
    Add("Tyrande! What are you doing here? This battle does not concern you.", "泰兰德！你来这里干什么？这场战斗与你无关。");
    Add("U00A", "巫妖王");
    Add("UNIT LIMIT CHANGED", "单位上限改变");
    Add("Uanb", "阿努巴拉克");
    Add("Uear", "瓦罗克·萨鲁法尔");
    Add("Uktl", "克尔苏加德");
    Add("Uldum was once a vast jungle, until the Forge of Origination stationed there wiped the slate clean. Now, buried under the sands lies a veritable trove of ancient relics.", "奥丹姆曾是一片广袤的丛林，直到驻扎于此的起源熔炉将一切抹平。如今，黄沙之下埋藏着一座名副其实的古代圣物宝库。");
    Add("Ulthar Shadowcleave", "乌尔萨·裂影者");
    Add("Umal", "玛尔加尼斯");
    Add("Undead Scourge", "亡灵天灾");
    Add("Unique", "独特");
    Add("Unit", "单位");
    Add("Units", "单位");
    Add("Unknown", "未知");
    Add("Unspoiled Wilderness", "未染之地");
    Add("Unyielding pride of the Warsong Clan, forged in battle and bound by honor", "战歌氏族不屈的骄傲，于战斗中铸就，为荣耀所约束。");
    Add("Upgrade your {from} to a {to}", "将你的 {from} 升级为 {to}");
    Add("Upper Elemental production building.", "上级元素生产建筑。");
    Add("Upper Netherstorm is continously wracked by devastating magical storms. Lands such as these represent opportunity for our people, as starved for mana as they are.", "上层虚空风暴持续遭受毁灭性魔法风暴的侵袭。对我们这些极度渴求魔法值的人民而言，这样的土地正是机遇所在。");
    Add("Ursula Snakemane", "厄苏拉·蛇鬃");
    Add("Usage: -faction control|uncontrol <faction|all>", "用法：-faction control|uncontrol <阵营|all>");
    Add("Usage: -faction defeat <faction>", "用法：-faction defeat <阵营>");
    Add("Usage: -faction set <faction>", "用法：-faction set <阵营>");
    Add("Usage: -faction team <faction> <team>", "用法：-faction team <阵营> <队伍>");
    Add("Usage: -help [page]", "用法：-help [页码]");
    Add("Usage: -power list <faction>", "用法：-power list <阵营>");
    Add("Usage: -power remove <faction> <key>", "用法：-power remove <阵营> <键名>");
    Add("Usage: -quest <complete|fail|uncomplete|undiscover> <faction> <key>", "用法：-quest <complete|fail|uncomplete|undiscover> <阵营> <键名>");
    Add("Usage: -quest list <faction>", "用法：-quest list <阵营>");
    Add("Use -bench <spell> <targets> <samples> [fixture]. See -bench help.", "用法：-bench <法术> <目标数> <采样次数> [fixture]。详见 -bench help。");
    Add("Uther Lightbringer is a paragon of Light and a champion of Lordaeron. His example inspires many man to rise up.", "光明使者乌瑟尔是圣光的典范，也是洛丹伦的勇士。他的表率激励着无数人奋起。");
    Add("Uther has achieved the status of living legend, inspiring the men and women of Lordaeron to strive for greatness.", "乌瑟尔已成为活着的传奇，激励着洛丹伦的男男女女追求伟大。");
    Add("Uther the Lightbringer makes his last stand, perishing in the defense of the light. Lordaeron, and humanity itself, has lost one of its finest exemplars in this dark hour.", "光明使者乌瑟尔做出了最后的抵抗，在为圣光而战中阵亡。在这黑暗的时刻，洛丹伦乃至全人类失去了一位最杰出的楷模。");
    Add("Utic", "提克迪奥斯");
    Add("Uvar", "瓦里玛萨斯");
    Add("Vaelis Moonweaver", "维利斯·织月者");
    Add("Vaelith Dawntracker", "维利斯·逐晨者");
    Add("Vaelith Shadowfin", "维利斯·影鳍");
    Add("Vaeloria Starbreaker", "瓦洛莉亚·破星者");
    Add("Val'anyr, Hammer of Ancient Kings", "瓦兰奈尔，远古王者之锤");
    Add("Valyssia Stormsentinel", "瓦莉西亚·风暴哨兵");
    Add("Vandrel Flamewarden", "凡德雷尔·烈焰守卫");
    Add("Vargoth Deathfang", "瓦格斯·死牙");
    Add("Varian has come to relieve the Nethergarde garrison.", "瓦里安前来接应守望堡的驻军。");
    Add("Varimathras", "瓦里玛萨斯");
    Add("Varok Grimfang", "瓦罗克·厉牙");
    Add("Vashj", "瓦丝琪");
    Add("Veknar the Spined", "棘刺者维克纳尔");
    Add("Velarith Moonwarden", "维拉里斯·月卫");
    Add("Velen has liberated Argus and re-assembled the Crown of Triumvirate", "维伦已解放阿古斯，并重新拼合了执政团之冠");
    Add("Velkrath the Creeper", "爬行者维尔克拉斯");
    Add("Velkris Doomcaller", "维尔克里斯·唤厄者");
    Add("Velyra Blackfin", "维莉拉·黑鳍");
    Add("Ven'Gyr", "维恩基尔");
    Add("Verbs: {verbs}.", "子命令：{verbs}。");
    Add("Vereesa Windrunner", "温蕾萨·风行者");
    Add("Very well. Our first priority is to set up a base camp with proper defenses. There's no telling what's waiting for us out there in the shadows.", "很好。我们的第一要务是建立一座防守完备的基地。不知道会有什么样的危险在阴影中等待着我们。");
    Add("Vial of the Sunwell", "太阳之井水瓶");
    Add("Victor Helmstrike", "维克托·舵击");
    Add("Vile betrayer! You are not fit enough to even carry your father's name! Why Uther ever vouched for you is beyond me. You've stripped him of his honor by casting yours to the winds! You deserve a gruesome death, boy!", "大逆不道的叛徒！你辱没了你父亲的英名！我真是搞不懂，当初乌瑟尔为什么要担保你。你不光舍弃了自己的荣耀，还把他的荣誉也糟蹋殆尽！你不得好死，小子！");
    Add("Vol'jin, foremost Shadow Hunter of the Darkspear Tribe, welcomes Thrall to his village with open arms. The trolls of the Echo Isles unanimously agree to join the new Horde.", "暗矛部族最杰出的暗影猎手沃金张开双臂欢迎萨尔来到他的村庄。回音群岛的巨魔一致同意加入新部落。");
    Add("Vornath Doomblade", "沃纳斯·末日之刃");
    Add("Vornax the Burrower", "掘地者沃纳克斯");
    Add("Vorpal Blades", "斩首之刃");
    Add("Vorrak the Ravager", "蹂躏者沃拉克");
    Add("Vorrik the Shadowleg", "影足者沃里克");
    Add("Vote Game Mode", "投票选择游戏模式");
    Add("Vote to forfeit the game.", "投票放弃本局游戏。");
    Add("Warchief, our ship sustained heavy damage when we passed through the raging maelstrom. It's unsalvageable.", "大酋长，我们的舰船在穿过汹涌的大漩涡时严重受损，已经无法修复了。");
    Add("Warden Shadowsong", "守望者影歌");
    Add("Warglaives of Azzinoth", "埃辛诺斯战刃");
    Add("Warmaul", "战槌");
    Add("Warrior Hero, adept at debuffing enemies.", "战斗型英雄，擅长削弱敌人。");
    Add("Warrior Hero, adept at enduring and strengthening nearby allies.", "战斗型英雄，擅长承受伤害并强化附近的友军。");
    Add("Warrior Hero, excels at enduring.", "战斗型英雄，擅长承受伤害。");
    Add("Warriors of the N'raqi.", "恩拉基的战士。");
    Add("Warsong Clan", "战歌氏族");
    Add("Water Prison", "水牢");
    Add("We have a thriving Discord community at {url}", "我们有一个活跃的 Discord 社区：{url}");
    Add("We have extracted a single vial of the Sunwell's energies. Though the well remains functional, its vibrancy has been visibly diminished by our theft.", "我们已从太阳之井中抽取了一小瓶能量。井虽仍能运作，但我们的窃取已令它的光辉明显黯淡。");
    Add("We have gained a new Forgotten One.", "我们获得了一个新的被忘却者。");
    Add("We have lost contact with the Elemental Realm, conquer Uldum to access the Vortex Pinnacle.", "我们已与元素位面失去联系。征服奥丹姆，方能进入旋云之巅。");
    Add("We have rebuilt the Exodar. Its systems thrum to life, pulsating with crystalline energy.", "我们重建了埃索达。它的系统重新运转起来，涌动着水晶能量。");
    Add("We must establish a forward base in Desolace to stop Night elf incursions.", "我们必须在凄凉之地建立一座前进基地，以阻止暗夜精灵的侵犯。");
    Add("We still don't have full control of Skywall. If we defeat the trolls of Zul'Farrak, we could use their power to secure dominion over the Throne of the Four Winds.", "我们仍未完全掌控天空之墙。若能击败祖尔法拉克的巨魔，便可借其力量夺取四风王座的控制权。");
    Add("We traveled due west, as you instructed. This should be it.", "我们按照指引一路西行。应该就是这里。");
    Add("We've prepared for your coming, Arthas. My brethren and I have erected auras that will destroy any undead that pass through them.", "我们已为你的到来做好了准备，阿尔萨斯。我和我的同胞们已布下光环，任何穿过它们的亡者都将被毁灭。");
    Add("Welcome, Prince Arthas. The men and I are honored by your presence.", "欢迎，阿尔萨斯王子。你的到来让我和将士们倍感荣幸。");
    Add("West-Zangarmarsh", "西赞加沼泽");
    Add("What are these vile serpents?", "这些蛇怪是从哪来的？");
    Add("What makes you say that?", "何以见得？");
    Add("What the... Am I hearing ghosts now?", "怎么回事……是鬼魂在说话吗？");
    Add("What would you know of us or our justice, naga witch?", "区区纳迦海巫懂什么暗夜精灵，懂什么正义？");
    Add("What? Who are... you?", "什么？你是……谁？");
    Add("When Hakkar the Soulflayer was defeated long ago, Zin'rokh was shattered and spread throughout the Troll tribes. The legendary blade could be reforged if its pieces could be unified once more.", "很久以前夺魂者哈卡败亡之时，辛洛斯被击碎，碎片散落于各个巨魔部族之中。若能将这些碎片重新集齐，这柄传奇之刃便可再度重铸。");
    Add("When a player leaves, their units are refunded, then their gold and hero experience are spread among their remaining allies.", "当一名玩家离开时，其单位会被折算返还，随后其黄金和英雄经验值会分配给仍在场的盟友。");
    Add("When a unit you control would take lethal damage, it has a {chance}% chance to instead be restored to {amount}% of its maximum hit points. Only active while your team controls a World Tree.", "当你控制的单位即将受到致命伤害时，有 {chance}% 的几率改为恢复至其最大生命值的 {amount}%。仅在你的队伍控制着一棵世界之树时生效。");
    Add("When activated, causes your units to teleport whenever you order them to patrol.", "激活后，当你命令单位巡逻时，它们将立即传送。");
    Add("When activated, grants vision of the entire map.", "激活后，获得整张地图的视野。");
    Add("When the Guardian Aegwynn defeated the fallen Titan Sargeras, she sealed his corpse within the temple that would come to be known as the Tomb of Sargeras. It lies still there, tempting those with the ambition to seize the power that remains within.", "当年守护者艾格文击败了堕落的泰坦萨格拉斯，将他的尸身封印在一座神庙中，那座神庙后来被称为萨格拉斯之墓。它至今仍静卧于彼处，诱惑着那些觊觎其中残存力量的野心之辈。");
    Add("When the city of Stratholme falls, Prince Arthas' despair will make him more susceptible to the power of the Lich King.", "当斯坦索姆城陷落时，阿尔萨斯王子的绝望将使他更易受巫妖王力量的侵蚀。");
    Add("When you unlock a hero through a Quest, you usually still need to summon that hero from an Altar.", "当你通过任务解锁一名英雄后，通常仍需要从祭坛召唤该英雄。");
    Add("Who are you, warrior?", "你是谁，战士？");
    Add("Who dares defile this ancient land? Who dares the wrath of Cenarius and the Night Elves?", "何人胆大包天，竟敢玷污这片远古之地，触怒塞纳留斯和暗夜精灵？");
    Add("Whole map revealed.", "已显示整张地图。");
    Add("Whole map unrevealed.", "已取消整张地图的显示。");
    Add("Win the game by capturing {cps} Control Points.", "占领{cps}个控制点即可赢得游戏。");
    Add("Windforging", "风铸");
    Add("With Argus finally under the Legion's control, the invasion of Azeroth can begin in earnest.", "随着阿古斯终于落入军团的掌控，对艾泽拉斯的入侵可以正式开始了。");
    Add("With Grizzly Hills now being tended by the Trees of Life, the time is ripe to regrow Andrassil in the hope that it can help reclaim this barren land.", "如今灰熊丘陵已由生命之树照料，重栽安达希尔的时机已经成熟——但愿它能帮助我们收复这片荒芜之地。");
    Add("With Mannoroth's death, the dark curse binding Grom Hellscream shatters like twisted iron chains. Freed from corruption and the demon's grasp, a redeemed Grom Hellscream rises once more, joining your ranks to fight for the honor of the Warsong Clan.", "随着玛诺洛斯的死亡，束缚格罗姆·地狱咆哮的黑暗诅咒如扭曲的铁链般寸寸断裂。摆脱腐化与恶魔的掌控后，得到救赎的格罗姆·地狱咆哮再度崛起，加入你的阵营，为战歌氏族的荣耀而战。");
    Add("With Nordrassil under your control, the druids falter, and the elemental forces of Skywall grow strengthened.", "诺达希尔落入你的掌控后，德鲁伊们阵脚大乱，天空之墙的元素之力则愈发强盛。");
    Add("With Outland now under Illidan's command, the Demon Hunter has returned to the Broken Isles in search of a legendary demonic artifact: the Eye of the Dark Titan, Sargeras.", "外域如今已在伊利丹的掌控之下，这位恶魔猎手返回破碎群岛，寻找一件传说中的恶魔神器：黑暗泰坦萨格拉斯之眼。");
    Add("With Shaladrassil back under Druidic control, its roots begin to swell and its branches bloom flowers anew, as if welcoming the Night elves home.", "随着莎拉达希尔重归德鲁伊的掌控，它的根须开始舒展，枝头再度绽放花朵，仿佛在欢迎暗夜精灵回家。");
    Add("With Zul'farrak under my control, I can extend the Hive to the sands of Tanaris.", "祖尔法拉克已在我们的掌控之下，我可以将虫巢延伸至塔纳利斯的沙海了。");
    Add("With food production now secured, we can settle Tempest Keep and start growing Ancients of the Arcane.", "粮食生产既已有了保障，我们便可进驻风暴要塞，着手培育奥术古树了。");
    Add("With our hives restored we can establish a forward one in Feralas.", "虫巢恢复之后，我们可以在菲拉斯建立一处前线虫巢。");
    Add("With our lands secured we must establish a forward base.", "领地既已稳固，我们必须建立一处前沿基地。");
    Add("With the Black Temple destroyed and our enemies defeated, we have secured a significant victory for Ironforge and our allies.", "黑暗神殿已被摧毁，敌人也已被击溃，我们为铁炉堡和盟友赢得了一场重大的胜利。");
    Add("With the Cult of the Damned established, the Scourge can plan their invasion of Lordaeron. The powerful Baron Rivendare has also joined the Cult to serve the Lich King.", "诅咒教派既已建立，天灾便可筹划对洛丹伦的入侵。强大的瑞文戴尔男爵也加入了教派，为巫妖王效力。");
    Add("With the Dark Portal now open, the forces of the Alliance pose a grave threat to Outland. Their cities must be destroyed if the Illidari are to thrive.", "黑暗之门既已开启，联盟的军队便对外域构成了严重威胁。若伊利达雷想要壮大，就必须摧毁他们的城市。");
    Add("With the Eye of Sargeras in hand, Illidan has become more demon than Night Elf. He now wields a tool capable of sundering the world.", "手握萨格拉斯之眼，伊利丹已变得更像恶魔，而非暗夜精灵。他如今掌握着一件足以撕裂世界的工具。");
    Add("With the Frozen Throne now ruptured beyond repair, Kil'jaeden's concerns over the upstart Lich King have been put to rest. The Deceiver upholds his end of the bargain, and bestows unto the Illidari his gift.", "冰封王座已破裂至无法修复，基尔加丹对那个狂妄巫妖王的顾虑也就此平息。欺诈者履行了他的承诺，将他的馈赠赐予伊利达雷。");
    Add("With the Monastery under Scarlet control, Sally Whitemane can be brought into the fold of the Crusade's leadership in earnest.", "修道院既已在血色十字军掌控之下，萨莉·怀特迈恩便能正式加入十字军的领导层。");
    Add("With the Plague now spreading amongst Lordaeron's populace, the Dreadlords set the second half of their plan in motion: a direct demonic incursion into the Eastern Kingdoms.", "随着瘟疫在洛丹伦的民众中蔓延，恐惧魔王启动了计划的第二阶段：一场对东部王国的直接恶魔入侵。");
    Add("With the Sunwell destroyed, the people of Quel'thalas are freed from its necrotic influence. Yet still they yearn for its magical energies - this addiction must be sated another way.", "太阳之井既已摧毁，奎尔萨拉斯的人民摆脱了它的亡者影响。然而他们仍旧渴求它的魔法能量——这份瘾癖必须以另一种方式满足。");
    Add("With the acquisition of a replacement power source, the Exodar's gemcrafters set to work reigniting the ship's dimensional portals. The Dimensional Generator can now now be used to travel the planes once more.", "在获得替代能源之后，埃索达的宝石匠们着手重新点燃飞船的维度传送门。维度发生器如今可以再度用于穿行于各个位面。");
    Add("With the adventurer party destroyed, no one stands in my way.", "冒险者小队已被摧毁，再无人能阻挡我的道路。");
    Add("With the defeat of C'Thun and N'Zoth, the Warsong champions channel the lingering echoes of the Old Gods' power. Both Kor'krons' and Blademasters' emerge reinvigorated to lead the Horde's conquests.", "随着克苏恩与恩佐斯的败亡，战歌氏族的勇士们汲取了上古之神残留的力量回响。库卡隆与剑圣皆焕然一新，将引领部落踏上征服之路。");
    Add("With the invaders defeated, I have retaken control of the Twilight landing.", "入侵者已被击溃，我重新夺回了暮光登陆场的控制权。");
    Add("With the local centaurs destroyed we can establish an outpost.", "当地的半人马已被消灭，我们可以建立一座前哨了。");
    Add("With the local wildlife destroyed we can establish a forward outpost.", "消灭当地的野生生物后，我们就可以建立一处前线前哨。");
    Add("With the shamans obliterated, my tendrils will reach every corner of this world", "萨满祭司已被消灭，我的触须将伸向这个世界的每一个角落。");
    Add("With the south coast of the Eastern Kingdoms now secure, High Bank has been established as a base of operations on an island near the Twilight Highlands.", "随着东部王国南海岸如今已然安定，滩头堡已在暮光高地附近的一座岛屿上建立，作为行动基地。");
    Add("With the swamps of Zangarmarsh secured, Lady Vashj and her Naga begin the work of rebuilding their clutcheries.", "赞加沼泽平定之后，瓦丝琪女士与她的纳迦开始重建他们的孵化场。");
    Add("With the threat of the Scourge and the Plague, Mograine has returned to help Lordaeorn in their dire times.", "面对天灾与瘟疫的威胁，莫格莱尼已归来，在危难之际助洛丹伦一臂之力。");
    Add("Without aid from the primary Sentinel force, Feathermoon Stronghold will undoubtedly fall to the assault of the Old Gods. We will need to restore it.", "若无哨兵主力部队的援助，羽月要塞必将陷落于上古之神的攻势之下。我们必须重建它。");
    Add("Wizards of the Kirin Tor! I am Arthas, first of the Lich King's death knights! I demand that you open your gates and surrender to the might of the Scourge!", "肯瑞托的法师们！我是阿尔萨斯，巫妖王的首席死亡骑士！我命令你们打开大门，向天灾军团投降！");
    Add("World-Shaman", "救世萨满");
    Add("Worshipper and structure summoner of C'thun.", "克苏恩的膜拜者与建筑召唤者。");
    Add("Wretched Night Elves. We are the Naga! We are the future!", "卑劣的暗夜精灵。我们是纳迦！我们就是未来！");
    Add("Xal'atath, Blade of the Black Empire", "萨拉塔斯，黑暗帝国之刃");
    Add("Xalorath Seaheart", "萨洛拉斯·海洋之心");
    Add("Xaxion", "萨克西昂");
    Add("Xylaris the Chitinous", "甲质者希拉里斯");
    Add("Xylaris the Webweaver", "织网者希拉里斯");
    Add("Y'Shaarj", "亚煞极");
    Add("Yes! I feel the power once again! Come, my warriors; drink from the dark waters, and you will be reborn!", "没错！我再次感受到了力量！来吧，我的战士们；饮下这黑暗之水，你们将获得重生！");
    Add("Yes, I've heard this rhetoric before. You orcs will never learn!", "对，这种鬼话我听多了。你们兽人根本毫无长进！");
    Add("Yes, great one. I am the summoner.", "是的，尊神。是我召唤了您。");
    Add("Yes, it has. Well, I guess we should get underway.", "对，时光飞逝啊。好吧，那么我们差不多该出发了。");
    Add("Yogg-Saron has been consumed. His genome has been added to the brood!", "尤格-萨隆已被吞噬。他的基因组已加入虫群！");
    Add("Yogg-Saron is still imprisoned and weak, but holds great power. If he is released and vanquished, I can consume his power and infuse it into my the Qiraji.", "尤格-萨隆仍被囚禁，力量虚弱，却依然蕴藏伟力。若能将他释放并击败，我便能吞噬他的力量，注入我的其拉虫人体内。");
    Add("Yogg-Saron rests dormant in Ulduar but his corruption seeps out from his prison. Once we are strong enough, we should open his prison and confront the Old God.", "尤格-萨隆沉睡在奥杜尔之中，但他的腐化正从牢笼中渗出。待我们足够强大，就应打开他的牢笼，直面这位上古之神。");
    Add("Yor'sahj needs souls to awaken the Maw of Shu'ma, a terrible Forgotten one, for me. Destroying and ravaging one of the mortals great cities will grant him the souls he needs.", "约尔萨吉需要灵魂，才能为我唤醒舒玛之口——一个可怕的被忘却者。摧毁并蹂躏一座凡人巨城，便能为他提供所需的灵魂。");
    Add("You are no longer invited to join the {team}.", "你不再受邀加入{team}。");
    Add("You are not in a team.", "你不在任何队伍中。");
    Add("You are not welcome here. I am Sylvanas Windrunner, Ranger-General of Silvermoon. I advise you to turn back now.", "这里不欢迎你。我是银月城的游侠将军，希尔瓦娜斯·风行者。我建议你现在就滚回去。");
    Add("You are playing as the accursed {faction}.\n\nYou start beyond the Greymane Wall at Pyrewood Village;\n\nYou must raise an army and fight back against the feral wolves of Silverpine and the bandit lords of Durnholde that have taken over Southern-Lordaeron.\n\nOnce you have reclaimed Southern-Lordaeron, open Greymane's Gate and march North to assist Lordaeron and Dalaran with the plague, if it's not too late.", "你正扮演受诅咒的{faction}。\n\n你从格雷迈恩之墙外的焚木村启程。\n\n你必须组建军队，反击占据南洛丹伦的银松森林野狼与敦霍尔德强盗领主。\n\n收复南洛丹伦之后，打开格雷迈恩之门北上，协助洛丹伦与达拉然应对瘟疫——如果还来得及的话。");
    Add("You are playing as the ancient {faction}.\n\nYou begin isolated in the deepest parts of Mount Hyjal near the World Tree.\n\nThe Old Gods are gathering to burn Ashenvale forest and the World Tree. Cenarius has emerged from his seclusion to stop them. Use him to awaken Malfurion from his slumber as soon as possible.\n\nGather your forces and strike before the Old Gods can organize their efforts.", "你正扮演古老的{faction}。\n\n你孤立地起始于海加尔山深处、世界之树附近。\n\n上古之神正在集结，意图焚毁灰谷森林与世界之树。塞纳留斯已结束隐居前来阻止他们。用他尽快唤醒沉睡的玛法里奥。\n\n集结你的军队，在上古之神组织起来之前发动攻击。");
    Add("You are playing as the bloodthirsty {faction}.\n\nYou begin in Nagrand, cut off from your forces in Hellfire Citadel. You must raise an army and quickly conquer Outland.\n\nOnce Outland is under your control, gather your hordes and prepare to invade Azeroth through the Dark Portal.\n\nThe Alliance is gathering outside the Dark Portal to stop you, so prepare for a very hard breakout.", "你正扮演嗜血的{faction}。\n\n你起始于纳格兰，与地狱火堡垒的部队失去联系。你必须组建军队，迅速征服外域。\n\n外域到手之后，集结你的部众，准备经黑暗之门入侵艾泽拉斯。\n\n联盟正在黑暗之门外集结以阻止你，做好苦战突围的准备。");
    Add("You are playing as the ever-watchful {faction}.\n\nThe Druids are slowly waking from their slumber, and it falls to you to drive back the Old Gods' invaders from Kalimdor until then.\n\nYour first mission is to race down the coast to Feathermoon Stronghold, a powerful Sentinel bastion on the southern half of the continent.\n\nOnce you have secured your holdings, gather your army and destroy the Old Gods. Be cautious—they will outnumber you if given time to establish a foothold in Azeroth.", "你正扮演时刻警戒的{faction}。\n\n德鲁伊仍在缓慢苏醒，在那之前，击退上古之神入侵者、守住卡利姆多的重任就落在你肩上。\n\n你的首个任务是沿海岸南下抵达羽月要塞——这座强大的哨兵堡垒位于大陆南半部。\n\n稳固领地后，集结军队消灭上古之神。务必谨慎——若给他们时间在艾泽拉斯站稳脚跟，他们的人数将远超于你。");
    Add("You are playing as the exiled {faction}.\n\nYou begin on Azuremyst Island, amid the wreckage of your flight from the Burning Legion.\n\nFurther inland your Night-elf allies will need your help against the Old Gods. Quickly build your base and gain entry to the Exodar.\n\nPower up your buildings with your Arcane Wells to unlock powerful global abilities.", "你正扮演流亡的{faction}。\n\n你起始于秘蓝岛，身处逃离燃烧军团时的残骸之中。\n\n更深处，你的暗夜精灵盟友需要你协助对抗上古之神。迅速建起基地并进入埃索达。\n\n用你的奥术之井强化建筑，以解锁强大的全局技能。");
    Add("You are playing as the fierce and relentless {faction}.\n\nBegin swiftly by rescuing your Chieftain, Grom Hellscream, who is trapped in battle and consumed by demonic fury. His survival is paramount.\n\nWith Grom secured, expand your dominance by subduing or pillaging nearby races to bolster your clan's strength.\n\nWork closely with your new elven allies—only together can you overcome the looming threat of the Old Gods.", "你正扮演凶猛而顽强的{faction}。\n\n首先迅速行动，救出你的酋长格罗姆·地狱咆哮——他身陷重围，被恶魔的狂怒所吞噬。他的生死至关重要。\n\n格罗姆脱险之后，再通过征服或劫掠附近的种族来扩张你的统治，壮大氏族的实力。\n\n与你的新精灵盟友紧密合作——唯有携手，才能战胜上古之神迫近的威胁。");
    Add("You are playing as the great {faction}.\n\nYou begin in Andorhal, isolated from your forces in the rest of the Kingdom, and the Plague of Undeath is imminent.\n\nSecure your major settlements by clearing out clusters of enemies and fortify your Kingdom as much as possible.\n\nIf you survive the Plague, sail to the frozen wasteland of Northrend and take the fight to the Lich King.", "你正扮演伟大的{faction}。\n\n你起始于安多哈尔，与王国其他地区的部队隔绝，而亡灵瘟疫已迫在眉睫。\n\n清除成群的敌人以稳固主要定居点，并尽可能加固你的王国。\n\n若能挺过瘟疫，就扬帆前往冰封的诺森德荒野，向巫妖王开战。");
    Add("You are playing as the honorable {clan}.\n\nYou begin in Ashenvale, make your way south to establish your bases, the Echo Isles and Thunder Bluff.\n\nYour allies will be coming south to help you defend against the Old Gods, do not engage them alone.", "你正扮演荣耀的{clan}。\n\n你从灰谷启程，一路南下建立你的基地：回音群岛与雷霆崖。\n\n你的盟友将南下协助你抵御上古之神，不要独自与它们交战。");
    Add("You are playing as the horrific {faction}.\n\nYou begin in Northrend, a vast and isolated land—perfect for raising an army of undying warriors to annihilate the living.\n\nThe local Nerubians have declared war on you. Destroy their decrepit holdings and slay their Queen to secure the continent.\n\nCoordinate with the Burning Legion and unleash the Plague of Undeath to sweep Lordaeron away.\n\nWhen the Plague strikes Lordaeron, you will have a choice of where to instantly transport all your military units.", "你正扮演恐怖的{faction}。\n\n你起始于诺森德——这片广袤而孤绝的土地，正适合组建不死大军来歼灭生者。\n\n当地的蛛魔已向你宣战。摧毁他们破败的据点，斩杀他们的女王，以稳固这片大陆。\n\n与燃烧军团配合，释放亡灵瘟疫，将洛丹伦一扫而空。\n\n当瘟疫降临洛丹伦时，你可以选择将所有军事单位瞬间传送至何处。");
    Add("You are playing as the long-enduring {faction}.\n\nYou begin in the Wetlands, separated from the rest of your forces. Conquer Loch Modan and Dun Morogh to regain access to your territories.\n\nStormwind is preparing for an invasion through the Dark Portal in the South. Muster your forces and aid them, or risk losing your strongest ally.", "你正扮演坚忍不拔的{faction}。\n\n你起始于湿地，与其余部队隔绝。征服洛克莫丹与丹莫罗，以重新连通你的领地。\n\n暴风城正在为南方穿越黑暗之门的入侵做准备。集结你的军队前去支援，否则你可能失去最强的盟友。");
    Add("You are playing as the maritime {faction}.\n\nYou begin on Balor Island, separated from your main forces in Kul Tiras. Unite your forces by eliminating your enemies in Tiragarde, Drustvar, and Stormsong Valley.\n\nStormwind is preparing for an invasion through the Dark Portal in the South. Muster the Admiralty and assist them, or risk losing your strongest ally.", "你正扮演海上的{faction}。\n\n你起始于巴洛岛，与库尔提拉斯的主力隔绝。清除提拉加德、德鲁斯瓦与斯托颂谷地的敌人，以统一你的力量。\n\n暴风城正在为南方穿越黑暗之门的入侵做准备。集结海军部前去支援，否则你可能失去最强的盟友。");
    Add("You are playing as the mighty {faction}.\n\nYou begin isolated on Argus. Once the planet is under your control, you will unlock two teleporters to Northrend and Alterac.\n\nOn Azeroth, the Scourge will need your assistance to destroy the Kingdoms of Lordaeron, Dalaran, and Quel'Thalas.\n\nYour primary objective is to summon the great host of the Burning Legion. Invade the city of Dalaran, where the Book of Medivh is kept, and use it to open the Demon-gate to Argus.", "你正扮演强大的{faction}。\n\n你孤立地起始于阿古斯。掌控这颗星球后，你将解锁两座通往诺森德与阿拉希高地的传送门。\n\n在艾泽拉斯，天灾需要你的协助来摧毁洛丹伦、达拉然与奎尔萨拉斯诸国。\n\n你的首要目标是召唤燃烧军团的大军。攻入存放麦迪文之书的达拉然城，用它开启通往阿古斯的恶魔之门。");
    Add("You are playing as the power-hungry {faction}.\n\nYou begin in Netherstorm. Your first mission is to build three biodomes in the green areas protected by a bubble.\n\nUnite with your fel ally to push through the Dark Portal and destroy Stormwind.\n\nYour ultimate goal is to summon Kil'jaeden and annihilate your enemies.", "你正扮演渴求力量的{faction}。\n\n你起始于虚空风暴。你的首个任务是在气泡保护的绿色区域内建造三座生态穹顶。\n\n与你的邪能盟友联合，穿过黑暗之门摧毁暴风城。\n\n你的最终目标是召唤基尔加丹，歼灭你的敌人。");
    Add("You are playing as the proud {faction}.\n\nYou begin in Tranquillien, separated from Silvermoon. The Trolls of Zul'Aman have laid siege to the city and are preparing attacks on your base.\n\nTrain soldiers to repel the attacks, then gather enough strength to besiege Zul'Aman and take the head of Zul'jin.\n\nThe Plague of Undeath is imminent, and Lordaeron will soon need your help against the Scourge. Be ready to join them once you have secured Silvermoon and dealt with the Amani invasion.", "你正扮演骄傲的{faction}。\n\n你起始于塔奎林，与银月城隔绝。祖阿曼的巨魔已围困该城，并正准备攻击你的基地。\n\n训练士兵击退进攻，再积蓄足够的力量围攻祖阿曼，取下祖尔金的首级。\n\n亡灵瘟疫迫在眉睫，洛丹伦很快会需要你协助对抗天灾。稳固银月城、解决阿曼尼入侵之后，随时准备与他们汇合。");
    Add("You are playing as the steadfast {faction}.\n\nYou begin in Westfall, separated from the rest of the kingdom. Reunite your lands by liberating Darkshire, Lakeshire, and finally Stormwind City.\n\nOnce you have unified Stormwind's forces, race east to the Nethergarde Stronghold and prepare for the invasion of the Fel Horde.\n\nMake sure to communicate with your Dwarven and Kul Tiran allies, as they will be key to defeating the evil that lurks beyond the Dark Portal.", "你正扮演坚毅的{faction}。\n\n你起始于西部荒野，与王国其余地区隔绝。解放夜色镇、湖畔镇，最终收复暴风城，以重新统一你的领土。\n\n统一暴风城的军队之后，迅速东进至守望堡，为邪部落的入侵做好准备。\n\n务必与你的矮人与库尔提拉斯盟友保持沟通，他们是击败黑暗之门背后邪恶力量的关键。");
    Add("You are playing as the {faction}.", "你扮演的是 {faction}。");
    Add("You are playing as the {faction}.\n\nAt the start, clear Uldum and take control of Tanaris.\n\nCoordinate with your Qiraji ally to push back the Horde before the Druids can intervene.\n\nYou have a powerful event in the Burning of the World Tree. Use it at the right time to surprise the Druids and possibly attack them from behind.", "你正扮演{faction}。\n\n开局先清理奥丹姆，夺取塔纳利斯的控制权。\n\n与你的其拉虫人盟友配合，在德鲁伊插手之前击退部落。\n\n你握有「焚烧世界之树」这一强大事件。在恰当时机发动，可打德鲁伊一个措手不及，甚至从背后袭击他们。");
    Add("You are playing as the {faction}.\n\nYou start in Nyalotha, restore the city to its glory by repelling the invaders from Azeroth.\n\nThen, move onto Kalimdor with your allies. You will quickly run into the Sentinels.\n\nBe sure to train Forsaken Ones, they are powerful units.", "你正扮演{faction}。\n\n你起始于尼奥罗萨，击退来自艾泽拉斯的入侵者，让这座城市重归荣光。\n\n随后与盟友一同进军卡利姆多。你很快会遭遇哨兵。\n\n务必训练被遗忘者，他们是强大的单位。");
    Add("You are playing as {faction}.\n\nYou start deep in the tunnels of Ahn'qiraj. You will need to awaken C'thun and free yourself from the Titan Guardians.\n\nThen, quickly start making your move north, coordinate with your elemental ally to attack Kalimdor.\n\nYou do not possess boats, but your workers can burrow through water, use them to outmaneuver your enemies.", "你正扮演{faction}。\n\n你起始于安其拉隧道的深处。你需要唤醒克苏恩，摆脱泰坦守护者的束缚。\n\n随后迅速北上，与你的元素盟友配合进攻卡利姆多。\n\n你没有船只，但你的工人可以掘穿水域，用他们来迂回包抄敌人。");
    Add("You are playing the wise {faction}.\n\nYou begin in the Hillsbrad Foothills, separated from the main forces of Dalaran. To unlock Dalaran, you must capture Shadowfang Keep, which has been encircled by monsters.\n\nOnce your territory is secured, you will need to prepare for the Plague of Undeath and the invasion of the Burning Legion. Lordaeron will surely need your help.\n\nYour mages are the finest in Azeroth. Be sure to utilize them alongside your heroes to turn the tide of battle.", "你正扮演睿智的{faction}。\n\n你起始于希尔斯布莱德丘陵，与达拉然的主力隔绝。要解锁达拉然，你必须夺取已被怪物包围的影牙城堡。\n\n领地稳固之后，你需要为亡灵瘟疫与燃烧军团的入侵做准备。洛丹伦必定需要你的协助。\n\n你的法师是艾泽拉斯最优秀的。务必让他们与你的英雄并肩作战，以扭转战局。");
    Add("You are very brave to stand against me, little human. If only your countrymen had been as bold, I would have had more fun scouring your wretched nations from the world!", "你竟敢跟我作对，真有勇气，渺小的人类。要是你的同胞都和你一样有骨气，当初踏平你们可怜的王国时，我就能获得更多乐子了！");
    Add("You aren't registered with the MMD system yet.", "你尚未在 MMD 系统中注册。");
    Add("You called my name, puny lich, and I have come. You are Kel'Thuzad, are you not?", "你呼唤了我的名字，渺小的巫妖，我来了。你就是克尔苏加德？");
    Add("You can change alliances by using the commands -invite, -uninvite, -join, and -unally.", "你可以使用 -invite、-uninvite、-join 和 -unally 命令来改变同盟关系。");
    Add("You can leave your current alliances by typing -unally, but you won't be able to join a new one.", "你可以输入 -unally 退出当前的同盟，但之后将无法加入新的同盟。");
    Add("You can now train Blue Dragons from Military Quarters and the Nexus.", "你现在可以从军事区与魔枢训练蓝龙。");
    Add("You can now train Siege Ancients at the Ancient of War.", "现在你可以在战争古树训练攻城古树。");
    Add("You can now train Thunder Eagles at the High Tower.", "你现在可以在高塔训练雷鹰了。");
    Add("You can now train Wardens from the {vault} and from {bastion}s.", "你现在可以从{vault}和{bastion}训练守望者了。");
    Add("You can now train Warlocks at the Consortium", "你现在可以在星界财团训练术士了");
    Add("You can now train up to {limit} units of type {unit}.", "你现在最多可以训练{limit}个{unit}。");
    Add("You can summon Khadgar from the Altar of Kings", "你可以从列王祭坛召唤卡德加");
    Add("You can summon Medivh from the Altar of Knowledge", "你可以从知识祭坛召唤麦迪文");
    Add("You can summon Tortolla from the Altar of Elders", "你可以在长者祭坛召唤托尔托拉");
    Add("You can train and control Ghouls, Abominations, Frost Wyrms, and Crypt Fiends.", "你可以训练并控制食尸鬼、憎恶、冰霜巨龙和地穴恶魔。");
    Add("You can't forfeit before turn {turn}.", "在第{turn}回合之前不能弃权。");
    Add("You can't invite yourself to your own team.", "你不能邀请自己加入自己的队伍。");
    Add("You cannot research {research}. All resources spent on it have been refunded.", "你无法研究{research}。其消耗的所有资源均已返还。");
    Add("You control all CPs {rect} ({current}/{max})", "你控制着 {rect} 的所有控制点（{current}/{max}）");
    Add("You control {target}", "你控制着 {target}");
    Add("You control {target} and all nearby creeps are dead ({current}/{max})", "你控制着 {target}，且附近所有野怪均已死亡（{current}/{max}）");
    Add("You don't have", "你没有");
    Add("You gain a research improving all of your units, the Crowns of Lordaeron and Stormwind are merged, and Arthas gains", "你获得一项强化所有单位的研发，洛丹伦王冠与暴风城王冠合而为一，阿尔萨斯获得");
    Add("You gain a research improving all of your units, the Crowns of Lordaeron and Stormwind are merged, and Arthas gains 10000 experience", "你获得一项强化所有单位的研究，洛丹伦与暴风城的王冠合而为一，阿尔萨斯获得 10000 点经验值");
    Add("You gain a research improving all of your units, the Crowns of Lordaeron and Stormwind are merged, and Varian gains 10 Strength and 10 Agility", "你获得一项可强化你所有单位的研究，洛丹伦王冠与暴风王冠合而为一，瓦里安获得 10 点力量和 10 点敏捷");
    Add("You gain control of Echo Isles, and learn to train Vol'jin from the Altar of Storms", "你获得回音群岛的控制权，并可以在风暴祭坛中训练沃金");
    Add("You gain control of Nethergarde", "你获得守望堡的控制权");
    Add("You gain control of a small base in Shadowforge City and can train the hero Dagran Thaurassian from the Altar of Fortitude", "你获得暗炉城内一座小型基地的控制权，并可在坚韧祭坛中训练英雄达格兰·索瑞森");
    Add("You gain the Kil'jaeden's Cunning Power, which causes your units' magic and spell damage to execute enemies", "你获得“基尔加丹的狡诈”之力，它会使你单位的魔法与法术伤害处决敌人");
    Add("You gain the Shaladrassil's Blessing Power", "你获得了“莎拉达希尔的祝福”之力");
    Add("You gain the powerful item, the Crown of the Triumvirate", "你获得强力物品：执政团之冠");
    Add("You have a hero at {rect}", "你在 {rect} 有一名英雄");
    Add("You have a unit at {rect}", "你在 {rect} 有一个单位");
    Add("You have already forfeited.", "你已弃权。");
    Add("You have become an observer.", "你已成为观战者。");
    Add("You have been invited to join the {team}. Type -join {team} to accept.", "你已受邀加入{team}。输入 -join {team}以接受。");
    Add("You have joined {team}.", "你已加入{team}。");
    Add("You have met the threshold for being eliminated from the game. Unless you raise your Control Point count above {cpThreshold}, raise food used above {foodThreshold} or your team retakes/gains an essential Legend, you will be defeated in {turns} {turnWord}.", "你已达到被淘汰出本局游戏的条件。除非你将控制点数量提升至{cpThreshold}以上、将已用人口提升至{foodThreshold}以上，或是你的队伍重新夺回/获得一位关键传奇，否则你将在{turns}{turnWord}后被击败。");
    Add("You have much to pay for, Illidan. I'm taking you back to your cell.", "你欠下了不少血债，伊利丹。我要把你送回牢里。");
    Add("You have not been invited to join {team}.", "你尚未受邀加入{team}。");
    Add("You hear the voice of the Dark Lord. He whispers to you through the blade you wield. What does he say, young human? What does the Dark Lord of the Dead tell you now?", "你听到的是黑暗之主的声音。它在通过你手中的剑向你低语。他说了什么，年轻的人类？统御亡者的黑暗之主对你说了什么？");
    Add("You look different, Illidan. I guess the Skull of Gul'dan didn't agree with you.", "你看起来不一样了，伊利丹。我猜是古尔丹之颅让你吃不消了？");
    Add("You must send at least 1 gold.", "你至少需要赠予 1 点黄金。");
    Add("You must specify a gold value as the second parameter.", "第二个参数必须指定黄金数量。");
    Add("You must specify a research ID of exactly 4 characters.", "你必须指定一个恰好 4 个字符的研发编号。");
    Add("You must specify a valid count as the second parameter.", "第二个参数必须指定有效的数量。");
    Add("You must specify a valid float as the first parameter.", "第一个参数必须指定有效的浮点数。");
    Add("You must specify a valid integer as the first parameter.", "第一个参数必须指定有效的整数。");
    Add("You must specify a valid object type ID as the first parameter.", "第一个参数必须指定有效的对象类型编号。");
    Add("You must specify a valid player number as the first parameter.", "第一个参数必须指定有效的玩家编号。");
    Add("You must specify a valid research level as the second parameter.", "第二个参数必须指定有效的研发等级。");
    Add("You must specify a whole number as the first parameter.", "第一个参数必须指定一个整数。");
    Add("You must specify an ability ID of exactly 4 characters.", "你必须指定一个恰好 4 个字符的技能编号。");
    Add("You must supply at least {min} parameters. If you're trying to use a parameter with multiple words, try enclosing it in quotes.", "你必须至少提供{min}个参数。如果你想使用包含多个词的参数，请尝试用引号将其括起来。");
    Add("You need to have a valid", "你需要拥有效的");
    Add("You orcs are weak, and hardly worth the effort. I wonder why Mannoroth even bothered with you.", "你们兽人简直弱小的不值一提！搞不懂玛诺洛斯为什么要在你们身上浪费时间！");
    Add("You too, Arthas. It's been awhile since a prince escorted me anywhere.", "彼此彼此，阿尔萨斯。上一次有王子为我护驾，已经是很久以前的事情了。");
    Add("You too, lad. I'm pleased that King Terenas sent you to help me.", "我也是，孩子。泰瑞纳斯国王派你来帮助我，真是太好了。。");
    Add("You waste your breath, Mal'Ganis. I heed only the voice of Frostmourne now.", "省点口舌吧，玛尔加尼斯。我脑海里只有霜之哀伤的声音。");
    Add("You will be able to train Fusillier from the Chapter House and to launch the Kalimdor Expedition", "你将能够从分会所训练火枪手，并发起卡利姆多远征");
    Add("You will gain Mannoroth as a temporary unit, all your orcs except your Kor'kron Elites will gain 200 hit points and chaos damage. After 4 min, your units will revert to normal and Mannoroth will become hostile.", "你将获得玛诺洛斯作为临时单位，除库卡隆精英外，你所有的兽人将获得 200 点生命值和混乱攻击。4 分钟后，你的单位将恢复原状，玛诺洛斯将转为敌对。");
    Add("You're not selecting any Legends.", "你当前没有选中任何传奇单位。");
    Add("You're not selecting any units.", "你当前没有选中任何单位。");
    Add("You're out of your league, old king. You should have stayed hidden underground.", "你已经不中用了，老国王。你应该乖乖躲在地底下的。");
    Add("You've come far enough, little warden. Your vaunted night elf justice has no jurisdiction here.", "到此为止了，小守望者。你们暗夜精灵所谓的正义，在这里可派不上用场。");
    Add("You've taken everything I ever cared for, Arthas. Vengeance is all I have left.", "你夺走了我曾珍视的一切，阿尔萨斯。我只剩下复仇了。");
    Add("Your Construction Sites can be upgraded", "你的建筑工地可以升级");
    Add("Your Control Points gain an additional level each turn.", "你的控制点每回合额外获得一个等级。");
    Add("Your Control Points gain {bonus} additional levels each turn.", "你的控制点每回合额外获得{bonus}个等级。");
    Add("Your Control Points increase your units' movement speed by 15% in a large radius.", "你的控制点会在较大范围内使你的单位移动速度提高 15%。");
    Add("Your Orc units have a {chance}% chance on attack to call down a lightning bolt dealing {damage} magic damage. Thrall instead has a 100% chance.", "你的兽人单位在攻击时有{chance}% 的几率召下一道闪电，造成{damage}点魔法伤害。萨尔则有 100% 的几率。");
    Add("Your casters and Paladins gain 200 hit points and 5 damage, and Paladins gain the Reincarnation ability", "你的施法单位与圣骑士获得 200 点生命值和 5 点伤害，圣骑士获得重生技能");
    Add("Your existing forces are removed, then you restart the game as the Scarlet Crusade in Tyr's Hand", "你现有的部队将被移除，随后你将以提尔之手的血色十字军重新开始游戏");
    Add("Your father ruled this land for seventy years, and you've ground it to dust in a matter of days.", "你的父亲统治了这片土地七十年，你却用了几天就让它化为乌有。");
    Add("Your non-Resistant units have a {chance}% chance to rematerialize in {location} upon death.", "你的非抗性单位死亡时有{chance}% 的几率在{location}重塑。");
    Add("Your petty magics will not stop me, Antonidas.", "你那可悲的魔法可阻止不了我，安东尼达斯。");
    Add("Your units are damaged for {damage}% of the mana they spend on spells. Units that die from this effect are reanimated as hostile Wretched.", "你的单位每消耗法力值施放法术，就会受到相当于消耗量{damage}%的伤害。因此效果而死亡的单位会被复活为敌对的失心者。");
    Add("Your units' Magic attacks and spell damage execute enemy units with less than {percentage}% hit points.", "你单位的魔法攻击与法术伤害会处决生命值低于 {percentage}% 的敌方单位。");
    Add("Your {unit1}s and {unit2} gain 400 hit points", "你的{unit1}和{unit2}获得 400 点生命值");
    Add("Your {unit} gain the Unholy Archon ability.", "你的{unit}获得邪恶执政官技能。");
