  /// <summary>
  /// Records one entry. Writing to the dictionary directly keeps the entries out of a collection
  /// initialiser, which the transpiler cannot compile at this size.
  /// </summary>
  private void Add(string english, string chinese)
  {
    _entries[english] = chinese;
  }
